Object.assign(window.TEM8_DICTIONARY, {"hide":{"oxford":{"phon":"haɪd","pos":"verb","senses":[{"en":"to put or keep somebody/something in a place where they/it cannot be seen or found","cn":"藏；隐蔽","g":"[transitive]","ex":{"en":"He hid the letter in a drawer.","cn":"他把信藏在抽屉里。"}},{"en":"to go somewhere where you hope you will not be seen or found","cn":"躲避；隐匿","g":"[intransitive, transitive]","lab":"figurative","ex":{"en":"Quick, hide!","cn":"快，躲起来！"}},{"en":"to cover somebody/something so that they/it cannot be seen","cn":"遮住；遮挡","g":"[transitive]","ex":{"en":"He hid his face in his hands.","cn":"他用手捂住了脸。"}},{"en":"to keep something secret, especially your feelings","cn":"掩盖，隐瞒（尤指感情）","g":"[transitive]","ex":{"en":"They didn't try to hide the fact that the film was a remake.","cn":"这部电影是翻拍的，他们并没有试图掩盖这一事实。"}},{"en":"a place from which people can watch wild animals or birds, without being seen by them","cn":"（观看野生动物的）隐蔽处，藏身处","g":"[countable]","lab":"British English","pos":"noun"},{"en":"an animal’s skin, especially when it is bought or sold or used for leather","cn":"（尤指买卖或用作皮革的）皮，毛皮","g":"[countable, uncountable]","ex":{"en":"boots made from buffalo hide","cn":"用水牛皮做的靴子"},"pos":"noun"},{"en":"used to refer to somebody’s life or safety when they are in a difficult situation","cn":"（困境中的）生命，人身安全","g":"[singular]","lab":"especially North American English, informal，，","ex":{"en":"All he's worried about is his own hide (= himself).","cn":"他所担心的只是他自己的生命安全。"},"pos":"noun"}]},"collins":{"senses":[{"pos":"VERB 动词","cn":"把…藏起来;隐藏","en":"If you hide something or someone, you put them in a place where they cannot easily be seen or found.","ex":{"en":"He hid the bicycle in the hawthorn hedge","cn":"他把自行车藏在山楂树篱中。"}},{"pos":"VERB 动词","cn":"躲藏;隐藏","en":"If you hide or if you hide yourself, you go somewhere where you cannot easily be seen or found.","ex":{"en":"At their approach the little boy scurried away and hid","cn":"他们走近时，小男孩急忙跑开藏了起来。"}},{"pos":"VERB 动词","cn":"捂住（脸）;将（脸）埋进","en":"If you hide your face, you press your face against something or cover your face with something, so that people cannot see it.","ex":{"en":"She hid her face under the collar of his jacket and she started to cry","cn":"她将脸埋在他外套的衣领下，开始哭了起来。"}},{"pos":"VERB 动词","cn":"隐瞒;使不外露","en":"If you hide what you feel or know, you keep it a secret, so that no one knows about it.","ex":{"en":"Lee tried to hide his excitement","cn":"李试图掩饰自己的激动心情。"}},{"pos":"VERB 动词","cn":"掩蔽;遮盖","en":"If something hides an object, it covers it and prevents it from being seen.","ex":{"en":"The man's heavy moustache hid his upper lip completely","cn":"那个男人浓密的髭须完全遮住了他的上唇。"}},{"pos":"N-COUNT 可数名词","cn":"（狩猎或观察、拍摄野生动物等的）隐蔽处，藏身处","en":"A hide is a place which is built to look like its surroundings. Hides are used by people who want to watch or photograph animals and birds without being seen by them."},{"pos":"N-VAR 可变名词","cn":"兽皮;毛皮","en":"A hide is the skin of a large animal such as a cow, horse, or elephant, which can be used for making leather.","ex":{"en":"...the process of tanning animal hides.","cn":"鞣制兽皮的工序"}}]},"media":{"uk":"media/uk/hide__gb_1.mp3","us":"media/us/hide__us_1.mp3"},"examples":[{"en":"They hid me from the police in their attic.","cn":"他们把我藏在他们的阁楼上躲避警察。"},{"en":"No amount of make-up could hide her age.","cn":"再多的化妆品也遮掩不住她的年龄。"}]},"hinting":{"lemma":"hint"},"highway":{"media":{"uk":"media/uk/highway__gb_1.mp3","us":"media/us/highway__us_1.mp3"},"oxford":{"phon":"ˈhaɪweɪ","pos":"noun","senses":[{"en":"a main road for travelling long distances, especially one connecting and going through cities and towns","cn":"（尤指城镇间的）公路，干道，交通要道","lab":"especially North American English","ex":{"en":"Plans were being made for the construction of a new interstate highway system.","cn":"正在制定建设新的州际公路系统的计划。"}},{"en":"a public road","cn":"公用通道","lab":"British English, formal，，","ex":{"en":"A parked car was obstructing the highway.","cn":"一辆停放的汽车堵住了通道。"}}]},"collins":{"senses":[{"pos":"N-COUNT 可数名词","cn":"（尤指城市间的）公路","en":"A highway is a main road, especially one that connects towns or cities.","ex":{"en":"I crossed the highway, dodging the traffic.","cn":"我避开车流穿过了公路。"}}]},"examples":[{"en":"A parked car was obstructing the highway.","cn":"一辆停放的汽车堵住了通道。"},{"en":"Highway patrol officers closed the road.","cn":"公路巡警关闭了这条路。"}]},"high-speed":{"oxford":{"phon":"ˌhaɪ ˈspiːd","pos":"adjective","senses":[{"en":"that travels, works or happens very fast","cn":"高速的；高效率的；迅速的","ex":{"en":"We are talking about a network of modern highways, high-speed trains, airports and air routes.","cn":"我们谈的是一个由现代高速公路、高速列车、机场和空中航线组成的网络。"}}]},"media":{"img":["media/pic/trains_comp.jpg","media/thumb/highspeedtrain.jpg"],"uk":"media/uk/high_speed_1_gb_1.mp3","us":"media/us/high_speed_1_us_1.mp3"},"examples":[{"en":"a high-speed car chase","cn":"高速汽车追逐"},{"en":"a high-speed train","cn":"高速列车"}]},"hi":{"oxford":{"phon":"haɪ","pos":"exclamation","senses":[{"en":"used to say hello","cn":"（招呼语）你好，嗨","ex":{"en":"Hi guys!","cn":"嗨，伙计们！"}}]},"collins":{"senses":[{"pos":"CONVENTION 惯用语","cn":"（用于非正式场合）嗨，你好","en":"In informal situations, you say 'hi' to greet someone.","ex":{"en":"'Hi, Liz,' she said shyly.","cn":"“你好，利兹，”她腼腆地说。"}}]},"media":{"uk":"media/uk/hi__gb_1.mp3","us":"media/us/hi__us_1.mp3"},"examples":[{"en":"Hi guys!","cn":"嗨，伙计们！"},{"en":"Hi, there! How're you doing?","cn":"喂！你好吗？"}]},"himself":{"media":{"uk":"media/uk/himself__gb_1.mp3","us":"media/us/himself__us_1.mp3"},"oxford":{"phon":"hɪmˈself","pos":"pronoun","senses":[{"en":"used when the man or boy who performs an action is also affected by it","cn":"（用作男性的反身代词）他自己，自己","ex":{"en":"He introduced himself.","cn":"他作了自我介绍。"}},{"en":"used to emphasize the male subject or object of a sentence","cn":"（强调句中的男性主语或宾语）","ex":{"en":"The doctor said so himself.","cn":"是医生本人这么说的。"}}]},"collins":{"senses":[{"pos":"PRON-REFL 反身代词","cn":"他自己;它自己（指雄性动物）","en":"You use himself to refer to a man, boy, or male animal.","ex":{"en":"He poured himself a whisky and sat down in the chair","cn":"他给自己倒了一杯威士忌，然后坐在椅子上。"}},{"pos":"PRON-REFL 反身代词","cn":"（书面英语中泛指人）他自己，她自己（有些人不喜欢这种用法，更倾向于使用 himself or herself 或 themselves）","en":"In written English, himself is sometimes used to refer to a person without saying whether that person is a man or a woman. Some people dislike this use and prefer to use 'himself or herself' or 'themselves'.","ex":{"en":"The child's natural way of expressing himself is play","cn":"孩子表达自己的本能方法就是玩耍。"}},{"pos":"PRON-REFL 反身代词","cn":"（一些宗教中指）上帝","en":"In some religions, Himself is used to refer to God.","ex":{"en":"He thanked God for concealing Himself from the wise and revealing Himself to the simple.","cn":"他感谢上帝，因为上帝在自作聪明的人面前自行隐匿，在心地纯洁的人面前则显现神迹。"}},{"pos":"PRON-REFL-EMPH 强调反身代词","cn":"（用于加强语气，有时代替 him 充当宾语）他本人，它本身","en":"You use himself to emphasize the person or thing that you are referring to. Himself is sometimes used instead of 'him' as the object of a verb or preposition.","ex":{"en":"There's no evidence that the Prime Minister himself cancelled the visit.","cn":"没有证据表明是首相本人取消了访问。"}}]},"examples":[{"en":"He has the house to himself during the week.","cn":"一周之中除周末外他可以一人住这座房子。"},{"en":"He didn't seem quite himself this morning.","cn":"他今天上午似乎有点不对劲。"}]},"hiding":{"media":{"uk":"media/uk/hiding__gb_1.mp3","us":"media/us/hiding__us_1.mp3"},"oxford":{"phon":"ˈhaɪdɪŋ","pos":"noun","senses":[{"en":"the state of being hidden","cn":"隐藏；躲藏","g":"[uncountable]","ex":{"en":"We spent months in hiding.","cn":"我们躲藏了好几个月。"}},{"en":"the act of hiding something","cn":"隐瞒；掩盖","g":"[uncountable]","ex":{"en":"I could understand the hiding of certain military secrets.","cn":"我能理解隐藏某些军事秘密的做法。"}},{"en":"a physical punishment, usually involving being hit hard many times","cn":"体罚；痛打","g":"[countable, usually singular]","lab":"especially British English, informal，，","ex":{"en":"to give somebody/get a (good) hiding","cn":"给某人／遭到一顿（狠）揍"}}]},"collins":{"senses":[{"pos":"N-UNCOUNT 不可数名词","cn":"躲藏;藏匿","en":"If someone is in hiding, they have secretly gone somewhere where they cannot be seen or found.","ex":{"en":"Gray is thought to be in hiding near the France/Italy border","cn":"他们认为格雷藏在法国和意大利边境附近。"}},{"pos":"N-COUNT 可数名词","cn":"痛打;狠揍","en":"If you give someone a hiding, you punish them by hitting them many times."},{"pos":"PHRASE 短语","cn":"白白浪费时间;白费工夫;毫无成功希望","en":"If you say that someone who is trying to achieve something is on a hiding to nothing, you are emphasizing that they have absolutely no chance of being successful.","ex":{"en":"As regards commercial survival, a car manufacturer capable of making only 50,000 cars a year is on a hiding to nothing.","cn":"谈到商业生存，一个年产只有5万辆的汽车制造厂家是毫无成功希望的。"}}]},"examples":[{"en":"( figurative ) The team got a hiding in their last game.","cn":"那支球队在最后一场比赛中被打得一败涂地。"},{"en":"After the trial, she had to go into hiding for several weeks.","cn":"审讯后她不得不躲藏了几个星期。"}],"base":"hide"},"hispanic":{"oxford":{"phon":"hɪˈspænɪk","pos":"adjective","senses":[{"en":"of or connected with Spain or Spanish-speaking countries, especially those of Latin America","cn":"西班牙的；西班牙语国家（尤指拉丁美洲）的"},{"en":"a person whose first language is Spanish, especially one from a Latin American country living in the US or Canada","cn":"母语为西班牙语的人（尤指住在美国或加拿大的拉丁美洲人）","pos":"noun"}]},"collins":{"senses":[{"pos":"ADJ 形容词","cn":"拉美裔美国籍的","en":"A Hispanic person is a citizen of the United States of America who originally came from Latin America, or whose family originally came from Latin America.","ex":{"en":"...a group of Hispanic doctors in Washington","cn":"华盛顿的一群拉美裔美国籍医生"}}]},"media":{"uk":"media/uk/hispanic__gb_1.mp3","us":"media/us/hispanic__us_1.mp3"},"examples":[{"en":"In California, Hispanics make up 19.2 percent of the population.","cn":"在加利福尼亚﹐西裔美国人占总人口的19.2%。"},{"en":"Miami’s Hispanic community","cn":"迈阿密的西裔美国人社区"}]},"highlights":{"lemma":"highlight","media":{"uk":"media/uk/highlight__gb_1.mp3","us":"media/us/highlight__us_1.mp3"}},"hindu":{"oxford":{"phon":"ˈhɪnduː","pos":"adjective","senses":[{"en":"connected with Hinduism or people who are Hindus","cn":"印度教的；印度教教徒的","ex":{"en":"a Hindu temple","cn":"印度教庙宇"}},{"en":"a person whose religion is Hinduism","cn":"印度教教徒","pos":"noun"}]},"collins":{"senses":[{"pos":"N-COUNT 可数名词","cn":"印度教徒","en":"A Hindu is a person who believes in Hinduism and follows its teachings."},{"pos":"ADJ 形容词","cn":"印度教的","en":"Hindu is used to describe things that belong or relate to Hinduism.","ex":{"en":"...a Hindu temple.","cn":"印度教寺庙"}}]},"media":{"uk":"media/uk/hindu__gb_1.mp3","us":"media/us/hindu__us_1.mp3"},"examples":[{"en":"a Hindu temple","cn":"印度教庙宇"}]},"historical":{"media":{"uk":"media/uk/historical__gb_1.mp3","us":"media/us/historical__us_1.mp3"},"oxford":{"phon":"hɪˈstɒrɪkl","pos":"adjective","senses":[{"en":"connected with the past","cn":"（有关）历史的","ex":{"en":"You must place these events in their historical context.","cn":"必须把这些事件与其历史背景联系起来看。"}},{"en":"connected with the study of history","cn":"有关历史研究的；历史学的","ex":{"en":"historical documents/records/research","cn":"史学文献／档案／研究"}},{"en":"about people and events in the past","cn":"历史题材的","ex":{"en":"a historical novel/setting","cn":"历史小说／背景"}}]},"collins":{"senses":[{"pos":"ADJ 形容词","cn":"历史（上）的","en":"Historical people, situations, or things existed in the past and are considered to be a part of history.","ex":{"en":"...an important historical figure.","cn":"重要的历史人物"}},{"pos":"ADJ 形容词","cn":"（书籍、电影或图片）描述历史的，基于史实的","en":"Historical books, films, or pictures describe or represent people, situations, or things that existed in the past.","ex":{"en":"He is writing a historical novel about nineteenth-century France.","cn":"他正在写一本描述19世纪法国的历史小说。"}},{"pos":"ADJ 形容词","cn":"历史学科的;史学的","en":"Historical information, research, and discussion is related to the study of history.","ex":{"en":"...historical records.","cn":"史籍"}},{"pos":"ADJ 形容词","cn":"历史背景的;历史视角的","en":"If you look at an event within a historical context, you look at what was happening at that time and what had happened previously, in order to judge the event and its importance.","ex":{"en":"It was this kind of historical context that Morris brought to his work","cn":"莫里斯的作品正是基于这样一种历史背景。"}}]},"examples":[{"en":"You must place these events in their historical context.","cn":"必须把这些事件同它们的历史环境联系起来看。"},{"en":"The building is of historical importance.","cn":"这栋建筑有重要的历史研究价值。"}]},"highlight":{"media":{"uk":"media/uk/highlight__gb_1.mp3","us":"media/us/highlight__us_1.mp3"},"oxford":{"phon":"ˈhaɪlaɪt","pos":"verb","senses":[{"en":"to emphasize something, especially so that people give it more attention","cn":"突出；强调","ex":{"en":"The report highlighted the importance of exercise to maintain a healthy body.","cn":"报告强调了锻炼对保持健康体魄的重要性。"}},{"en":"to mark part of a text with a special coloured pen, or to mark an area on a computer screen, to emphasize it or make it easier to see","cn":"将（文本的某部分）用彩笔做标记；将（计算机屏幕的某区域）增强亮度；使醒目","ex":{"en":"I've highlighted the important passages in yellow.","cn":"我用黄色标出了重要段落。"}},{"en":"to make some parts of your hair a lighter colour than the rest by using a chemical substance on them","cn":"挑染（将部分头发染成浅色）","ex":{"en":"I’m having my hair highlighted.","cn":"我正在突出显示我的头发。"}},{"en":"the best, most interesting or most exciting part of something","cn":"最好（或最精彩、最激动人心）的部分","ex":{"en":"One of the highlights of the trip was seeing the Taj Mahal.","cn":"这次旅行中的最精彩的一件事是参观泰姬陵。"},"pos":"noun"},{"en":"areas of hair that are lighter than the rest, usually because a chemical substance has been put on them","cn":"亮色挑染的头发","g":"[plural]","ex":{"en":"She’s had blonde highlights put into her hair.","cn":"她的头发染上了金色的亮点。"},"pos":"noun"},{"en":"the light or bright part of a picture or photograph","cn":"（图画或照片的）强光部分","g":"[plural]","lab":"specialist","pos":"noun"}]},"collins":{"senses":[{"pos":"VERB 动词","cn":"使突出;强调;使注意","en":"If someone or something highlights a point or problem, they emphasize it or make you think about it.","ex":{"en":"Last year Collins wrote a moving ballad which highlighted the plight of the homeless","cn":"去年，柯林斯写了一首动人的抒情歌曲，突出描绘了无家可归者的苦境。"}},{"pos":"VERB 动词","cn":"（用荧光笔）标出;（在计算机屏幕上）突出显示","en":"To highlight a piece of text means to mark it in a different colour, either with a special type of pen or on a computer screen.","ex":{"en":"Highlight the chosen area by clicking and holding down the left mouse button.","cn":"点击并摁住鼠标左键将所选区域高亮显示。"}},{"pos":"N-COUNT 可数名词","cn":"最有趣（或最精彩、最重要）的部分","en":"The highlights of an event, activity, or period of time are the most interesting or exciting parts of it.","ex":{"en":"...a match that is likely to prove one of the highlights of the tournament","cn":"可能是本次联赛中最精彩的比赛之一"}},{"pos":"N-PLURAL 复数名词","cn":"挑染的头发;（头发经阳光照射后产生强光效果的）浅色部分","en":"Highlights in a person's hair are narrow lighter areas made by dyeing or sunlight."}]},"examples":[{"en":"The report highlights the major problems facing society today.","cn":"报告特别强调了当今社会所面临的主要问题。"},{"en":"One of the highlights of the trip was seeing the Taj Mahal.","cn":"这次旅行中的最精彩的一件事是参观泰姬陵。"}]},"hindering":{"lemma":"hinder"},"historically":{"oxford":{"phon":"hɪˈstɒrɪkli","pos":"adverb","senses":[{"en":"in a way that is connected with the past","cn":"历史地","ex":{"en":"The book is historically inaccurate.","cn":"这本书与史实不符。"}},{"en":"in a way that is connected with the study of history","cn":"与历史研究相关地；历史学地","ex":{"en":"historically significant documents","cn":"具有历史意义的文件"}}]},"media":{"uk":"media/uk/historically__gb_1.mp3","us":"media/us/historically__us_1.mp3"},"examples":[{"en":"Historically, there has always been a great deal of rivalry between the two families.","cn":"这两个家族世世代代对立斗争。"},{"en":"The book is historically inaccurate.","cn":"这本书与史实不符。"}]},"hijinks":{"ldoce":{"phon":"hwd","pos":"noun","senses":[{"en":"an American spelling of high jinks high jinks","cn":"的美式拼法"}]},"media":{"uk":"media/uk/hijinks__gb_1.mp3","us":"media/us/hijinks__us_1.mp3"},"oxford":{"phon":"ˈhaɪdʒɪŋks","pos":"noun","senses":[{"en":"lively and excited behaviour","cn":"狂欢作乐；喧闹"}]}},"hints":{"lemma":"hint"},"hits":{"lemma":"hit","media":{"uk":"media/uk/hit__gb_1.mp3","us":"media/us/hit__us_1.mp3"}},"hit":{"media":{"uk":"media/uk/hit__gb_1.mp3","us":"media/us/hit__us_1.mp3"},"oxford":{"phon":"hɪt","pos":"verb","senses":[{"en":"to bring your hand, or an object you are holding, against somebody/something quickly and with force","cn":"（用手或器具）击，打","g":"[transitive]","sc":"touch somebody/something with force","ex":{"en":"I was afraid he was going to hit me.","cn":"我怕他会打我。"}},{"en":"to come against something/somebody with force, especially causing damage or injury","cn":"碰撞；撞击（造成损伤）","g":"[transitive, intransitive]","sc":"touch somebody/something with force","ex":{"en":"The bus hit the bridge.","cn":"公共汽车撞到了桥上。"}},{"en":"to knock a part of your body against something","cn":"使（身体部位）碰上（某物）","g":"[transitive]","sc":"touch somebody/something with force","ex":{"en":"I must have hit my knee.","cn":"我肯定撞到了膝盖。"}},{"en":"to reach and touch a person or thing suddenly and with force","cn":"击中；命中","g":"[transitive, often passive]","sc":"touch somebody/something with force","ex":{"en":"The town was hit by bombs again last night.","cn":"这个镇子昨晚又一次遭到了轰炸。"}},{"en":"to bring a bat, etc. against a ball and push it away with force","cn":"击（球）","g":"[transitive]","sc":"ball","ex":{"en":"She hit the ball and ran to first base.","cn":"她击球后跑向一垒。"}},{"en":"to score points by hitting a ball","cn":"击球得分","g":"[transitive]","lab":"sport","sc":"ball","ex":{"en":"to hit a home run","cn":"打出本垒打"}},{"en":"to press something such as a button to operate a machine, etc.","cn":"按，压（按钮等）","g":"[transitive]","lab":"informal","sc":"press button","ex":{"en":"Hit the brakes!","cn":"踩刹车！"}},{"en":"to have a bad effect on somebody/something","cn":"产生不良影响；打击；危害","g":"[transitive, intransitive]","sc":"have bad effect","ex":{"en":"The tax increases will certainly hit the poor.","cn":"增税肯定会加重穷人的负担。"}},{"en":"to attack somebody/something","cn":"攻击；进攻；袭击","g":"[transitive, intransitive]","sc":"attack","ex":{"en":"We hit the enemy when they least expected it.","cn":"我们在敌人最意想不到的时候发动了进攻。"}},{"en":"to reach a place","cn":"到达（某地）","g":"[transitive]","lab":"informal","sc":"reach","ex":{"en":"Follow this footpath and you'll eventually hit the road.","cn":"沿着这条小路走，终会走上大路。"}},{"en":"to reach a particular level","cn":"达到（某水平）","g":"[transitive]","lab":"British English","sc":"reach","ex":{"en":"Temperatures hit 40° yesterday.","cn":"昨天气温高达 40 度。"}},{"en":"to experience something difficult or unpleasant","cn":"遇到（困难）；经历（不愉快的事情）","g":"[transitive]","lab":"informal","sc":"problem/difficulty","ex":{"en":"We seem to have hit a problem.","cn":"我们似乎遇到了问题。"}},{"en":"to come suddenly into your mind","cn":"使突然想起","g":"[transitive]","lab":"informal","sc":"suddenly realize","ex":{"en":"The idea hit me like a tornado.","cn":"这个想法猛然闯进我的脑海。"}},{"en":"to become widely available for sale","cn":"大量上市","g":"[transitive]","lab":"informal","sc":"become available","ex":{"en":"the latest board game to hit the market","cn":"最新上市的桌面游戏"}},{"en":"an act of hitting somebody/something with your hand or with an object held in your hand","cn":"打；击","sc":"act of hitting","ex":{"en":"Give it a good hit.","cn":"用力打它一下。"},"pos":"noun"},{"en":"an occasion when something that has been thrown, fired, etc. at an object reaches that object; the fact of being hit by something","cn":"命中；击中","sc":"act of hitting","ex":{"en":"We finished the first round with a score of two hits and six misses.","cn":"我们在第一轮结束时的分数是两次击中，六次未中。"},"pos":"noun"},{"en":"a person or thing that is very popular","cn":"很受欢迎的人（或事物）","sc":"something popular","ex":{"en":"He's just about to star in the hit musical, ‘Chicago’.","cn":"他即将出演热门音乐剧《芝加哥》。"},"pos":"noun"},{"en":"a successful pop song or record","cn":"风行一时的流行歌曲（或唱片）","sc":"pop music","ex":{"en":"They are about to release an album of their greatest hits.","cn":"他们即将发行收录他们最热门歌曲的专辑。"},"pos":"noun"},{"en":"an occasion on which a web page is displayed or a file is downloaded from the internet","cn":"（网页的）点击；（文件的）下载","lab":"computing","sc":"computing","ex":{"en":"Our website is getting a lot of hits from the USA.","cn":"我们的网站得到很多来自美国的点击。"},"pos":"noun"},{"en":"the fact of finding an item of data that matches a search","cn":"（信息检索的）匹配，结果","lab":"computing","sc":"computing","ex":{"en":"The search generated 1 848 hits.","cn":"这一搜索得到了 1 848 个相关结果。"},"pos":"noun"},{"en":"an amount of an illegal drug that is taken at one time","cn":"毒品的一剂","lab":"slang","sc":"of drug","ex":{"en":"a hit of cocaine/heroin","cn":"吸食可卡因/海洛因"},"pos":"noun"},{"en":"a violent crime or murder","cn":"暴力犯罪；凶杀","lab":"slang, especially North American English，，","sc":"murder","pos":"noun"}]},"collins":{"senses":[{"pos":"VERB 动词","cn":"打;击","en":"If you hit someone or something, you deliberately touch them with a lot of force, with your hand or an object held in your hand.","ex":{"en":"Find the exact grip that allows you to hit the ball hard","cn":"找到能让你大力击球的准确握拍方法。"}},{"pos":"VERB 动词","cn":"撞击;碰撞","en":"When one thing hits another, it touches it with a lot of force.","ex":{"en":"The car had apparently hit a traffic sign before skidding out of control","cn":"汽车显然是撞上了一个交通标志牌后打滑失控的。"}},{"pos":"VERB 动词","cn":"（炸弹、导弹）击中，命中","en":"If a bomb or missile hits its target, it reaches it.","ex":{"en":"...multiple-warhead missiles that could hit many targets at a time","cn":"可一次击中多个目标的多弹头导弹"}},{"pos":"VERB 动词","cn":"打击;使受严重影响","en":"If something hits a person, place, or thing, it affects them very badly.","ex":{"en":"The plan to charge motorists £75 a year to use the motorway is going to hit me hard","cn":"向汽车驾驶员每年收取75英镑高速公路使用费的计划将对我大为不利。"}},{"pos":"VERB 动词","cn":"使突然想起","en":"When a feeling or an idea hits you, it suddenly affects you or comes into your mind.","ex":{"en":"It hit me that I had a choice","cn":"我突然意识到我有选择的余地。"}},{"pos":"VERB 动词","cn":"达到（某一高点或低点）","en":"If you hit a particular high or low point on a scale of something such as success or health, you reach it.","ex":{"en":"He admits to having hit the lowest point in his life ","cn":"他承认自己跌到了一生中的最低谷。"}},{"pos":"N-COUNT 可数名词","cn":"成功而轰动（或风行）一时的事物（如唱片、电影或戏剧）","en":"If a CD, film, or play is a hit, it is very popular and successful.","ex":{"en":"The song became a massive hit in 1945.","cn":"这首歌在1945年风靡大江南北。"}},{"pos":"N-COUNT 可数名词","cn":"（网站的）点击，浏览，访问","en":"A hit is a single visit to a website.","ex":{"en":"Our small company has had 78,000 hits on its Internet pages.","cn":"我们这个小公司的因特网网页已经有了78,000次的点击量。"}},{"pos":"N-COUNT 可数名词","cn":"（在因特网上的）查询结果，检索结果","en":"If someone who is searching for information on the Internet gets a hit, they find a website where there is that information."},{"pos":"PHR-RECIP 相互短语","cn":"一见如故;合得来；投缘","en":"If two people hit it off, they like each other and become friendly as soon as they meet.","ex":{"en":"They hit it off straight away, Daddy and Walter","cn":"爸爸和沃尔特很快就一见如故。"}},{"pos":"PHRASE 短语","cn":"大受欢迎;深受…的喜爱;令…印象深刻","en":"If you make a hit with someone, they like you or are impressed by you when they meet you.","ex":{"en":"He made a hit with Lady Sopwith","cn":"他深受索普威思太太的喜爱。"}},{"pos":"","cn":"","en":"to hit the bottle→see: ; to hit the headlines→see: ; to hit home→see: ; to hit the nail on the head→see: ; to hit the road→see: ; to hit the roof→see: ; to hit someone for six→see: ;"},{"pos":"","cn":"","en":"相关词组：hit back hit on hit out hit upon"}]},"examples":[{"en":"In a rousing speech the minister hit out at racism in the armed forces.","cn":"在一次激励人心的讲话中，部长严厉抨击了军中的种族主义。"},{"en":"I couldn't remember where I'd seen him before, and then it suddenly hit me.","cn":"起初我想不起以前在哪里见过他，后来猛然记起来了。"}]},"high-end":{"oxford":{"phon":"ˌhaɪ ˈend","pos":"adjective","senses":[{"en":"expensive and of high quality","cn":"高档的；高端的；价高质优的"}]},"collins":{"senses":[{"pos":"ADJ 形容词","cn":"（尤指电子产品）最高档的，高端的，最昂贵的","en":"High-end products, especially electronic products, are the most expensive of their kind.","ex":{"en":"...high-end personal computers and computer workstations.","cn":"高端个人计算机和计算机工作站"}}]},"media":{"uk":"media/uk/high_end_1_gb_1.mp3","us":"media/us/high_end_1_us_1.mp3"},"examples":[{"en":"high-end computer memory chips","cn":"高端电脑存储芯片"}]},"hillside":{"media":{"uk":"media/uk/hillside__gb_1.mp3","us":"media/us/hillside__us_1.mp3"},"oxford":{"phon":"ˈhɪlsaɪd","pos":"noun","senses":[{"en":"the side of a hill","cn":"小山坡","ex":{"en":"The crops will not grow on exposed hillsides.","cn":"在裸露的山坡上庄稼没法生长。"}}]},"collins":{"senses":[{"pos":"N-COUNT 可数名词","cn":"（小山的）山坡，山腰","en":"A hillside is the sloping side of a hill."}]},"examples":[{"en":"Our hotel was on the hillside overlooking the lake.","cn":"我们的旅馆位于可俯瞰湖水的小山坡上。"},{"en":"The crops will not grow on exposed hillsides.","cn":"在裸露的山坡上庄稼没法生长。"}]},"hides":{"lemma":"hide"},"hideously":{"media":{"uk":"media/uk/hideously__gb_1.mp3","us":"media/us/hideously__us_1.mp3"},"collins":{"senses":[{"pos":"ADV 副词","cn":"可怕地;丑陋地","en":"You use hideously to emphasize that something is very ugly or unattractive.","ex":{"en":"Everything is hideously ugly","cn":"一切都非常丑陋。"}},{"pos":"ADV-GRADED 副词","cn":"令人无法接受地;极其恶劣地","en":"You can use hideously to emphasize that something is very unpleasant or unacceptable.","ex":{"en":"...a hideously complex program.","cn":"极其复杂的程序"}}]},"examples":[{"en":"His face was hideously deformed.","cn":"他的脸严重变形。"},{"en":"Dinnertime that day was hideous.","cn":""}],"oxford":{"phon":"ˈhɪdiəsli","pos":"adverb","senses":[{"en":"in a very ugly or unpleasant way","cn":"十分丑陋的；令人厌恶的","ex":{"en":"His face was hideously deformed.","cn":"他的脸严重变形，十分可怕。"}}]}},"hire":{"media":{"uk":"media/uk/hire__gb_1.mp3","us":"media/us/hire__us_1.mp3"},"oxford":{"phon":"ˈhaɪə(r)","pos":"verb","senses":[{"en":"to give somebody a job","cn":"聘用；录用；雇用","g":"[transitive, intransitive]","lab":"British English","ex":{"en":"She was hired three years ago.","cn":"她是三年前录用的。"}},{"en":"to employ somebody for a short time to do a particular job","cn":"临时雇用","g":"[transitive]","ex":{"en":"to hire a lawyer/detective","cn":"聘请律师；雇用侦探"}},{"en":"to pay money to borrow something for a short time","cn":"租用；租借","g":"[transitive]","lab":"especially British English","ex":{"en":"to hire a room/studio","cn":"租房间；租工作室"}},{"en":"the act of paying to use something for a short time","cn":"租借；租用；租赁","g":"[uncountable]","lab":"especially British English","ex":{"en":"a hire car","cn":"供租用的汽车"},"pos":"noun"},{"en":"a person who has recently been given a job by a company","cn":"新雇员；新员工","g":"[countable]","lab":"especially North American English","ex":{"en":"New hires get raises after a set period of time.","cn":"新雇用的人在规定时间以后可获晋升。"},"pos":"noun"}]},"collins":{"senses":[{"pos":"VERB 动词","cn":"雇用","en":"If you hire someone, you employ them or pay them to do a particular job for you.","ex":{"en":"Sixteen of the contestants have hired lawyers and are suing the organisers","cn":"有16名参赛者已经请了律师，正在起诉主办方。"}},{"pos":"VERB 动词","cn":"（短期）租用","en":"If you hire something, you pay money to the owner so that you can use it for a period of time.","ex":{"en":"To hire a car you must produce a passport and a current driving licence","cn":"租车须出示护照及有效驾照。"}},{"pos":"N-UNCOUNT 不可数名词","cn":"租赁（业）;出租（业务）","en":"You use hire to refer to the activity or business of hiring something.","ex":{"en":"They booked our hotel, and organised car hire","cn":"他们为我们订好了旅馆并安排了租车事宜。"}},{"pos":"PHRASE 短语","cn":"供出租;待租","en":"If something is for hire, it is available for you to hire.","ex":{"en":"Fishing tackle is available for hire.","cn":"有钓具可供出租。"}},{"pos":"","cn":"","en":"相关词组：hire out"}]},"examples":[{"en":"They hired a firm of consultants to design the new system.","cn":"他们请了一家咨询公司来设计新的系统。"},{"en":"He does the hiring and firing in our company.","cn":"他在我们公司负责员工的聘用和辞退。"}]},"history":{"media":{"uk":"media/uk/history__gb_1.mp3","us":"media/us/history__us_1.mp3"},"oxford":{"phon":"ˈhɪstri","pos":"noun","senses":[{"en":"all the events that happened in the past","cn":"历史（指过去发生的所有事情）","g":"[uncountable]","ex":{"en":"The battle was a turning point in human history.","cn":"这场战役是人类历史的转折点。"}},{"en":"the past events connected with the development of a particular place, subject, etc.","cn":"（有关某个地方、主题等的）发展史，历史","g":"[singular, uncountable]","ex":{"en":"the history of science/music/philosophy","cn":"科学史；音乐史；哲学史"}},{"en":"the study of past events, especially as a subject at school or university","cn":"历史课；历史学","g":"[uncountable]","ex":{"en":"a history professor/teacher","cn":"历史教授／老师"}},{"en":"a written or spoken account of real past events","cn":"历史（指真实历史事件的记载或口述）","g":"[countable, uncountable]","ex":{"en":"She's writing a new history of Europe.","cn":"她正在写一部新的欧洲史。"}},{"en":"the set of facts that are known about somebody/something's past","cn":"（某人的）过往事迹；（某事物的）来历，沿革","g":"[countable]","ex":{"en":"I know nothing about his personal history.","cn":"我对他的个人历史一无所知。"}},{"en":"a record of something happening frequently in the past life of a person, family or place","cn":"个人经历；家族史；地方志","g":"[countable, usually singular]","ex":{"en":"He has a history of violent crime.","cn":"他有暴力犯罪的前科。"}},{"en":"a record kept by a web browser of the web pages and other files it has been used to access","cn":"（网页浏览和文件读取的）历史记录","g":"[uncountable]","ex":{"en":"Clearing your browser history prevents websites from following and tracking your actions.","cn":"清除浏览器历史记录可防止网站跟踪你的活动。"}},{"en":"a relationship between two people, groups, companies, etc. that started in the past and continued for a period of time, especially one involving bad or complicated feelings","cn":"纠葛关系；旧怨；过节","g":"[uncountable, singular]","ex":{"en":"Sure there's history between Anna Mae and me, like you said.","cn":"当然，我和安娜·梅之间有过节，就像你说的。"}},{"en":"a historical play","cn":"历史剧","g":"[countable]","ex":{"en":"Shakespeare's comedies, histories and tragedies","cn":"莎士比亚的喜剧、历史剧和悲剧"}}]},"collins":{"senses":[{"pos":"N-UNCOUNT 不可数名词","cn":"历史","en":"You can refer to the events of the past as history. You can also refer to the past events which concern a particular topic or place as its history.","ex":{"en":"The Catholic Church has played a prominent role throughout Polish history.","cn":"天主教会在整个波兰历史上曾发挥过举足轻重的作用。"}},{"pos":"N-UNCOUNT 不可数名词","cn":"历史学;史学","en":"History is a subject studied in schools, colleges, and universities that deals with events that have happened in the past."},{"pos":"N-COUNT 可数名词","cn":"过去事件的记载;发展史","en":"A history is an account of events that have happened in the past.","ex":{"en":"...his magnificent history of broadcasting in Canada.","cn":"他在加拿大辉煌的播音史"}},{"pos":"N-COUNT 可数名词","cn":"记录;习惯;（某地的）沿革","en":"If a person or a place has a history of something, it has been very common or has happened frequently in their past.","ex":{"en":"He had a history of drink problems","cn":"他过去酗酒度日。"}},{"pos":"N-COUNT 可数名词","cn":"履历;经历","en":"Someone's history is the set of facts that are known about their past.","ex":{"en":"He couldn't get a new job because of his medical history.","cn":"由于他的病史，他无法找到新的工作。"}},{"pos":"N-UNCOUNT 不可数名词","cn":"历史的陈迹;（无关紧要的）往事","en":"If you say that an event, thing, or person is history, you mean that they are no longer important.","ex":{"en":"The Charlottetown agreement is history.","cn":"夏洛特敦协定已成为历史。"}},{"pos":"PHRASE 短语","cn":"接下来的事就世人皆知了","en":"If you are telling someone about an event and say the rest is history, you mean that you do not need to tell them what happened next because everyone knows about it already.","ex":{"en":"We met at college, the rest is history.","cn":"我们是在上大学时认识的，接下来的事大家都知道了。"}}]},"examples":[{"en":"The area was inhabited long before the dawn of recorded history (= before people wrote about events).","cn":"早在有历史记载之前很久这个地区就有人居住了。"},{"en":"The school traces its history back to 1865.","cn":"这个学校的历史可以追溯到 1865 年。"}]},"higher":{"media":{"uk":"media/uk/higher__gb_1.mp3","us":"media/us/higher__us_1.mp3"},"oxford":{"phon":"ˈhaɪə(r)","pos":"adjective","senses":[{"en":"at a more advanced level; greater in rank or importance than others","cn":"高等级的；级别较高的；较重要的","ex":{"en":"The case was referred to a higher court.","cn":"案件转到了上级法院。"}},{"en":"(in Scotland) an exam taken in a particular subject at a higher level than National 3, 4 and 5 qualifications. Highers are usually taken around the age of 17 to 18.","cn":"学生高级证书考试（水平高于国家 3、4、5 级资格，应试年龄一般在 17 至 18 岁）","pos":"noun"}]},"collins":{"senses":[{"pos":"ADJ 形容词","cn":"（学历、文凭等）高级的，高等的","en":"A higher degree or diploma is a qualification of an advanced standard or level.","ex":{"en":"...a higher diploma in hotel management.","cn":"酒店管理高级证书"}}]},"examples":[{"en":"My mind was on higher things.","cn":"我那时想着更重要的事。"},{"en":"The case was referred to a higher court.","cn":"案件转到了上级法院。"}]},"high-impact":{"collins":{"senses":[{"pos":"ADJ 形容词","cn":"（锻炼）高强度的","en":"High-impact exercise puts a lot of stress on your body.","ex":{"en":"...high-impact aerobics.","cn":"高强度有氧健身操"}},{"pos":"ADJ 形容词","cn":"（材料）高强度的，承载重压的","en":"High-impact materials are very strong.","ex":{"en":"The durable high-impact plastic case is water resistant to 100 feet.","cn":"这种结实的高强度塑料盒子在水下100英尺以内是防水的。"}}]}},"his":{"media":{"uk":"media/uk/his__gb_1.mp3","us":"media/us/his__us_1.mp3"},"oxford":{"phon":"hɪz","pos":"determiner","senses":[{"en":"of or belonging to a man or boy who has already been mentioned or is easily identified","cn":"他的","ex":{"en":"James has sold his car.","cn":"詹姆斯把他的车卖了。"}},{"en":"of or belonging to God","cn":"上帝的；属于上帝的"},{"en":"of or belonging to him","cn":"他的；属于他的","ex":{"en":"He took my hand in his.","cn":"他握住我的手。"},"pos":"pronoun"}]},"collins":{"senses":[{"pos":"DET-POSS 所有格限定词","cn":"他的;（指雄性动物）它的","en":"You use his to indicate that something belongs or relates to a man, boy, or male animal.","ex":{"en":"Brian splashed water on his face, then brushed his teeth","cn":"布赖恩用水冲了把脸，然后刷牙。"}},{"pos":"DET-POSS 所有格限定词","cn":"（书面英语中泛指人）他的，她的（有些人不喜欢这种说法，更倾向于使用 his or her 或 their）","en":"In written English, his is sometimes used to refer to a person without saying whether that person is a man or a woman. Some people dislike this use and prefer to use 'his or her' or 'their'.","ex":{"en":"Formerly, the relations between a teacher and his pupils were dominated by fear on the part of the pupils","cn":"以往的师生关系主要是学生惧怕老师。"}},{"pos":"DET-POSS 所有格限定词","cn":"（一些宗教中指）上帝","en":"In some religions, His is used to refer to God.","ex":{"en":"...humble faith in God, and trust in His Church.","cn":"对上帝的谦卑信仰和对教会的信任"}}]},"examples":[{"en":"James has sold his car.","cn":"詹姆斯把他的车卖了。"},{"en":"He broke his leg skiing.","cn":"他滑雪时摔断了腿。"}]},"hint":{"oxford":{"phon":"hɪnt","pos":"noun","senses":[{"en":"something that you say or do in an indirect way in order to show somebody what you are thinking","cn":"暗示；提示；示意","ex":{"en":"He gave a broad hint (= one that was obvious) that he was thinking of retiring.","cn":"他几乎明示他正在考虑退休。"}},{"en":"something that suggests what will happen in the future","cn":"征兆；迹象","ex":{"en":"At the first hint of trouble, they left.","cn":"他们一发现有点不妙的迹象就离开了。"}},{"en":"a small amount of something","cn":"少许；少量","g":"[usually singular]","ex":{"en":"a hint of a smile","cn":"一丝笑意"}},{"en":"a small piece of practical information or advice","cn":"秘诀；窍门","g":"[usually plural]","ex":{"en":"handy hints on saving money","cn":"省钱妙诀"}},{"en":"to suggest something in an indirect way","cn":"暗示；透露；示意","ex":{"en":"What are you hinting at?","cn":"你在暗示什么？"},"pos":"verb"}]},"collins":{"senses":[{"pos":"N-COUNT 可数名词","cn":"暗示","en":"A hint is a suggestion about something that is made in an indirect way.","ex":{"en":"The Minister gave a strong hint that the government were thinking of introducing tax concessions for mothers","cn":"部长明显地暗示政府正在考虑对母亲们实行税收减免。"}},{"pos":"VERB 动词","cn":"暗示;示意","en":"If you hint at something, you suggest it in an indirect way.","ex":{"en":"She suggested a trip to the shops and hinted at the possibility of a treat of some sort","cn":"她建议去逛逛商店，并暗示可能要请客。"}},{"pos":"N-COUNT 可数名词","cn":"有益的建议;不错的主意;好点子","en":"A hint is a helpful piece of advice, usually about how to do something.","ex":{"en":"Here are some helpful hints to make your journey easier","cn":"几条有用的建议可以让你的旅途更轻松。"}},{"pos":"N-SING 单数名词","cn":"少许;微量","en":"A hint of something is a very small amount of it.","ex":{"en":"She added only a hint of vermouth to the gin","cn":"她只在杜松子酒里加了少许苦艾酒。"}}]},"media":{"uk":"media/uk/hint__gb_1.mp3","us":"media/us/hint__us_1.mp3"},"examples":[{"en":"I thought they'd never go — some people just can't take a hint.","cn":"我以为他们永远也不会走的，有些人就是不会看眼色。"},{"en":"Sarah hoped he'd take the hint and leave her alone.","cn":"萨拉希望他能明白她的意思，不来打扰她。"}]},"hive":{"media":{"uk":"media/uk/hive__gb_1.mp3","us":"media/us/hive__us_1.mp3"},"oxford":{"phon":"haɪv","pos":"noun","senses":[{"en":"a structure made for bees to live in","cn":"蜂房；蜂箱","g":"[countable]","ex":{"en":"studying the life of bees in the hive","cn":"研究蜜蜂在蜂巢中的生活"}},{"en":"the bees living in a hive","cn":"一箱蜜蜂；蜂群","g":"[countable]"},{"en":"a place full of people who are busy","cn":"忙碌的场所；繁忙的地方","g":"[countable, usually singular]"},{"en":"red spots on the skin that itch (= make you want to rub your skin with your nails), caused by an allergic reaction, for example to certain foods","cn":"荨麻疹","g":"[uncountable, plural]","lab":"medical"}]},"collins":{"senses":[{"pos":"N-COUNT 可数名词","cn":"蜂房;蜂箱","en":"A hive is a structure in which bees are kept, which is designed so that the beekeeper can collect the honey that they produce."},{"pos":"N-COUNT 可数名词","cn":"熙熙攘攘的场所;人群忙碌的地方","en":"If you describe a place as a hive of activity, you approve of the fact that there is a lot of activity there or that people are busy working there.","ex":{"en":"In the morning the house was a hive of activity","cn":"早上，房子里一片繁忙景象。"}},{"pos":"N-UNCOUNT 不可数名词","cn":"荨麻疹","en":"Hives is a condition in which patches of your skin become red and very uncomfortable and itchy."},{"pos":"","cn":"","en":"相关词组：hive off"}]},"examples":[{"en":"The IT department is being hived off into a new company.","cn":"信息技术部正被分拆出来，成立新公司。"},{"en":"This marketplace was once a hive of activity.","cn":"这个市场曾经熙熙攘攘。"}]},"high-pitched":{"oxford":{"phon":"ˌhaɪ ˈpɪtʃt","pos":"adjective","senses":[{"en":"very high","cn":"很高的；尖利的","ex":{"en":"a high-pitched voice/whistle","cn":"尖嗓子；尖锐的口哨声"}}]},"collins":{"senses":[{"pos":"ADJ-GRADED 能被表示程度的副词或介词词组修饰的形容词","cn":"尖声的;音调高的","en":"A high-pitched sound is shrill and high in pitch.","ex":{"en":"A woman squealed in a high-pitched voice.","cn":"一个女人大声尖叫。"}}]},"media":{"uk":"media/uk/high_pitched_1_gb_1.mp3","us":"media/us/high_pitched_1_us_1.mp3"},"examples":[{"en":"a high-pitched voice/whistle","cn":"尖嗓子；尖锐的口哨声"}]},"highly":{"media":{"uk":"media/uk/highly__gb_1.mp3","us":"media/us/highly__us_1.mp3"},"oxford":{"phon":"ˈhaɪli","pos":"adverb","senses":[{"en":"very","cn":"很；非常","ex":{"en":"It is highly unlikely that she'll be late.","cn":"她不大可能会迟到。"}},{"en":"at or to a high standard, level or amount","cn":"高标准地；高级地；大量地","ex":{"en":"highly trained/educated","cn":"受过高级培训／高等教育"}},{"en":"with great respect or praise","cn":"钦佩地；赞赏地","ex":{"en":"I highly recommend this book.","cn":"我强烈推荐这本书。"}}]},"collins":{"senses":[{"pos":"ADV 副词","cn":"极其;非常","en":"Highly is used before some adjectives to mean 'very'.","ex":{"en":"Mr Singh was a highly successful salesman","cn":"辛格先生是个非常成功的推销员。"}},{"pos":"ADV-GRADED 副词","cn":"身居高位;高级别地","en":"You use highly to indicate that someone has an important position in an organization or set of people.","ex":{"en":"...a highly placed government advisor.","cn":"高级政府顾问"}},{"pos":"ADV-GRADED 副词","cn":"高水平地","en":"If someone is highly paid, they receive a large salary.","ex":{"en":"He was the most highly paid member of staff.","cn":"他是员工中薪酬最高的。"}},{"pos":"ADV-GRADED 副词","cn":"极为（赞许）;（评价）高的","en":"If you think highly of something or someone, you think they are very good indeed.","ex":{"en":"Daphne and Michael thought highly of the school.","cn":"达夫妮和迈克尔对那所学校评价很高。"}}]},"examples":[{"en":"Her novels are very highly regarded.","cn":"她的小说受到很高的评价。"},{"en":"It is highly unlikely that she'll be late.","cn":"她不大可能会迟到。"}]},"hidden":{"oxford":{"phon":"ˈhɪdn","pos":"adjective","senses":[{"en":"something that is hidden is kept or located in a place where it cannot be seen","cn":"隐藏的；隐匿的","ex":{"en":"Hidden dangers lurk in the ocean depths.","cn":"海洋深处隐藏着危险。"}},{"en":"secret","cn":"秘密的；保密的；隐蔽的","ex":{"en":"She felt sure the letter had some hidden meaning.","cn":"她确信那封信有言外之意。"}}]},"collins":{"senses":[{"pos":"","cn":"","en":"Hidden is the past participle of hide ."},{"pos":"ADJ 形容词","cn":"难以看见（或发现）的;隐藏的","en":"Hidden facts, feelings, activities, or problems are not easy to notice or discover.","ex":{"en":"Under all the innocent fun, there are hidden dangers, especially for children","cn":"在所有简单无害的娱乐项目背后都隐藏着危险，特别是对儿童而言。"}},{"pos":"ADJ 形容词","cn":"（地方）隐秘的","en":"A hidden place is difficult to find.","ex":{"en":"As you descend, suddenly you see at last the hidden waterfall.","cn":"一直往下走，最终你会突然看到那条隐秘的瀑布。"}}]},"media":{"uk":"media/ldoce/hwd/bre/6/hidden0205.mp3","us":"media/ldoce/hwd/ame/c/laadhidden.mp3"},"examples":[{"en":"Some areas can hold hidden dangers for dogs.","cn":"一些区域可能对狗有隐伏的危险。"},{"en":"the hidden meaning behind his words","cn":"他的言外之意"}],"base":"hide"},"hinder":{"oxford":{"phon":"ˈhɪndə(r)","pos":"verb","senses":[{"en":"to make it difficult for somebody to do something or for something to happen","cn":"阻碍；妨碍；阻挡","ex":{"en":"a political situation that hinders economic growth","cn":"妨碍经济发展的政治局面"}}]},"collins":{"senses":[{"pos":"VERB 动词","cn":"阻碍;妨碍;阻止","en":"If something hinders you, it makes it more difficult for you to do something or make progress.","ex":{"en":"Does the fact that your players are part-timers help or hinder you?","cn":"队员们都是兼职的，这对你有利还是不利？"}},{"pos":"VERB 动词","cn":"牵制，束缚（动作）","en":"If something hinders your movement, it makes it difficult for you to move forward or move around.","ex":{"en":"A thigh injury increasingly hindered her mobility","cn":"大腿受伤使她行动愈发不便。"}}]},"media":{"uk":"media/uk/hinder__gb_1.mp3","us":"media/us/hinder__us_1.mp3"},"examples":[{"en":"Some teachers felt hindered by a lack of resources.","cn":"有些教师因资源不足而感到困难重重。"},{"en":"An injury was hindering him from playing his best.","cn":"受伤后他无法发挥出最高水平。"}]},"high":{"media":{"uk":"media/uk/high__gb_1.mp3","us":"media/us/high__us_1.mp3"},"oxford":{"phon":"haɪ","pos":"adjective","senses":[{"en":"measuring a long distance from the bottom to the top","cn":"高的","sc":"from bottom to top","ex":{"en":"What's the highest mountain in the US?","cn":"美国哪座山最高？"}},{"en":"used to talk about the distance that something measures from the bottom to the top","cn":"有某高度的","sc":"from bottom to top","ex":{"en":"How high is Everest?","cn":"珠穆朗玛峰有多高？"}},{"en":"at a level that is a long way above the ground or above the level of the sea","cn":"（离地面）很高的；海拔很高的","sc":"far above ground","ex":{"en":"a high branch/shelf/window","cn":"高处的树枝／搁板／窗"}},{"en":"greater or better than normal in quantity or quality, size or degree","cn":"（数量、质量、体积或程度）高的，超乎寻常的","sc":"greater than normal","ex":{"en":"a high price/cost/speed/temperature","cn":"高价；高成本；高速；高温"}},{"en":"containing a lot of a particular substance","cn":"含某物多","sc":"containing a lot","ex":{"en":"a high potassium content","cn":"高钾含量"}},{"en":"near the top in rank, status or importance","cn":"上层的；地位（或重要性）高的","g":"[usually before noun]","sc":"rank/status","ex":{"en":"She has held high office under three prime ministers.","cn":"她曾在三任首相手下任过要职。"}},{"en":"of great value","cn":"价值高的","sc":"valuable","ex":{"en":"to play for high stakes","cn":"豪赌"}},{"en":"when a river or the tide is high, the water reaches a long way up the river bank, beach, etc.","cn":"高水位的；高潮位的","sc":"river/sea","ex":{"en":"The river was very high and threatening to flood.","cn":"这条河水位很高，有发洪水的危险。"}},{"en":"morally good","cn":"高尚的；崇高的","g":"[usually before noun]","sc":"ideals/principles","ex":{"en":"a man of high ideals/principles","cn":"有崇高理想／道德准则的人"}},{"en":"showing a lot of approval or respect for somebody","cn":"十分赞同的；非常尊敬的","g":"[usually before noun]","sc":"approving","ex":{"en":"She is held in very high regard by her colleagues.","cn":"她很受同事们的敬重。"}},{"en":"at the upper end of the range of sounds that humans can hear; not deep or low","cn":"高音的","sc":"sound","ex":{"en":"She has a high voice.","cn":"她嗓音很尖。"}},{"en":"used to describe the middle or the most attractive part of a period of time","cn":"中间的；全盛的","g":"[only before noun]","sc":"of period of time","ex":{"en":"high noon","cn":"正午"}},{"en":"beginning to go bad and having a strong smell","cn":"开始变质的；开始发馊的","sc":"food"},{"en":"behaving in an excited way because of the effects of alcohol or drugs","cn":"有醉意；表现兴奋","g":"[not before noun]","lab":"informal","sc":"on alcohol/drugs","ex":{"en":"He was high on drugs.","cn":"他吸毒得很厉害。"}},{"en":"produced with part of the tongue in the highest possible position without limiting the flow of air","cn":"闭的；舌位高的","lab":"phonetics","sc":"phonetics"},{"en":"at or to a position or level that is a long way up from the ground or from the bottom","cn":"在高处；向高处；高","sc":"far from ground/bottom","ex":{"en":"to climb/jump/leap high","cn":"爬／蹦／跳得高"},"pos":"adverb"},{"en":"at or to a large value, amount or price","cn":"（价值或价格）高；（数量）大","sc":"value/amount","ex":{"en":"Prices are expected to rise even higher this year.","cn":"预计今年价格会涨得更高。"},"pos":"adverb"},{"en":"to or at an important position","cn":"到高位；在高位","sc":"important position","ex":{"en":"She never rose very high in the company.","cn":"她在公司里从未升到很高的位置。"},"pos":"adverb"},{"en":"at a high pitch","cn":"音调高","sc":"sound","ex":{"en":"I can't sing that high.","cn":"我唱不了那么高的调子。"},"pos":"adverb"},{"en":"the highest level or number","cn":"最高水平；最大数量","sc":"level/number","ex":{"en":"to hit/reach a high","cn":"达到高水平"},"pos":"noun"},{"en":"an area of high air pressure; an anticyclone","cn":"高气压区；反气旋","sc":"weather","ex":{"en":"A high over southern Europe is bringing fine, sunny weather to all parts.","cn":"欧洲南部上空的高气压正给各地带来阳光灿烂的好天气。"},"pos":"noun"},{"en":"the highest temperature reached during a particular day, week, etc.","cn":"（某天、某星期等的）最高气温","sc":"weather","ex":{"en":"Highs today will be in the region of 25°C.","cn":"今天的最高气温将为 25 摄氏度左右。"},"pos":"noun"},{"en":"the feeling of extreme pleasure and excitement that somebody gets after taking some types of drugs","cn":"（毒品引致的）快感","lab":"informal","sc":"from drugs","ex":{"en":"The high lasted all night.","cn":"那种快感持续了一整夜。"},"pos":"noun"},{"en":"the feeling of extreme pleasure and excitement that somebody gets from doing something fun or being successful at something","cn":"极大欢乐；极度高兴；乐不可支","lab":"informal","sc":"from success/enjoyment","ex":{"en":"He was on a real high after winning the competition.","cn":"他赢了那场比赛后高兴极了。"},"pos":"noun"},{"en":"used in the name of a high school","cn":"（用于中学校名）","sc":"school","ex":{"en":"He graduated from Little Rock High in 2012.","cn":"他 2012 年毕业于小石城中学。"},"pos":"noun"}]},"collins":{"senses":[{"pos":"ADJ-GRADED 能被表示程度的副词或介词词组修饰的形容词","cn":"高的（不用于形容人或动植物）","en":"Something that is high extends a long way from the bottom to the top when it is upright. You do not use high to describe people, animals, or plants.","ex":{"en":"...a house, with a high wall all around it","cn":"四周围着高墙的房子"}},{"pos":"ADJ 形容词","cn":"高度为…的;有…高的","en":"You use high to talk or ask about how much something upright measures from the bottom to the top.","ex":{"en":"...an elegant bronze horse only nine inches high","cn":"只有9英寸高的精致青铜马雕塑"}},{"pos":"ADJ-GRADED 能被表示程度的副词或介词词组修饰的形容词","cn":"（相对地面、海平面、其他人或物）高的","en":"If something is high, it is a long way above the ground, above sea level, or above a person or thing.","ex":{"en":"I looked down from the high window","cn":"我从高高的窗口往下看。"}},{"pos":"ADJ-GRADED 能被表示程度的副词或介词词组修饰的形容词","cn":"（数量、程度、强度等）高的","en":"You can use high to indicate that something is great in amount, degree, or intensity.","ex":{"en":"The European country with the highest birth rate is Ireland","cn":"人口出生率最高的欧洲国家是爱尔兰。"}},{"pos":"ADJ-GRADED 能被表示程度的副词或介词词组修饰的形容词","cn":"（食物等）含…高的，富含…的","en":"If a food or other substance is high in a particular ingredient, it contains a large amount of that ingredient.","ex":{"en":"Don't indulge in rich sauces, fried food and thick pastry as these are high in fat.","cn":"不要吃太多浓酱汁、油炸食品和甜腻的油酥点心，因为这些食品的脂肪含量很高。"}},{"pos":"N-COUNT 可数名词","cn":"最高点;最高水平","en":"If something reaches a high of a particular amount or degree, that is the greatest it has ever been.","ex":{"en":"Traffic from Jordan to Iraq is down to a dozen loaded lorries a day, compared with a high of 200 a day","cn":"现在从约旦到伊拉克一天只有十几辆装货的卡车通过，而最高峰时可达到一天200辆。"}},{"pos":"ADJ-GRADED 能被表示程度的副词或介词词组修饰的形容词","cn":"（重要性）高的;重要的","en":"If you say that something is a high priority or is high on your list, you mean that you consider it to be one of the most important things you have to do or deal with.","ex":{"en":"The Labour Party has not made the issue a high priority","cn":"工党尚未将该问题列为优先考虑的事项。"}},{"pos":"ADJ-GRADED 能被表示程度的副词或介词词组修饰的形容词","cn":"（地位、职位）高的，显赫的","en":"Someone who is high in a particular profession or society, or has a high position, has a very important position and has great authority and influence.","ex":{"en":"Was there anyone particularly high in the administration who was an advocate of a different policy?","cn":"政府中有没有哪位高层人物支持采取不同政策？"}},{"pos":"ADJ 形容词","cn":"先进的;高级的;复杂的","en":"You can use high to describe something that is advanced or complex.","ex":{"en":"Neither Anna nor I are interested in high finance.","cn":"安娜和我对巨额融资都不感兴趣。"}},{"pos":"ADV-GRADED 副词","cn":"向高的目标（努力）","en":"If you aim high, you try to obtain or to achieve the best that you can.","ex":{"en":"You should not be afraid to aim high in the quest for an improvement in your income","cn":"想让自己的收入有所提高时，你应该敢于给自己设定高的目标。"}},{"pos":"ADJ-GRADED 能被表示程度的副词或介词词组修饰的形容词","cn":"（声望、评价）高的","en":"If someone has a high reputation, or people have a high opinion of them, people think they are very good in some way, for example at their work.","ex":{"en":"She has always had a high reputation for her excellent short stories","cn":"她一直因其优秀的短篇小说享有很高的声望。"}},{"pos":"ADJ-GRADED 能被表示程度的副词或介词词组修饰的形容词","cn":"（质量、标准）高的","en":"If the quality or standard of something is high, it is very good indeed.","ex":{"en":"This is high quality stuff","cn":"这东西质量很好。"}},{"pos":"ADJ-GRADED 能被表示程度的副词或介词词组修饰的形容词","cn":"崇高的;高尚的","en":"If someone has high principles, they are morally good.","ex":{"en":"He was a man of the highest principles.","cn":"他是个道德崇高的人。"}},{"pos":"ADJ-GRADED 能被表示程度的副词或介词词组修饰的形容词","cn":"（音调）高而尖的，高的","en":"A high sound or voice is close to the top of a particular range of notes.","ex":{"en":"Her high voice really irritated Maria.","cn":"她的尖嗓门实在让玛丽亚很恼火。"}},{"pos":"ADJ-GRADED 能被表示程度的副词或介词词组修饰的形容词","cn":"（河流）水位高的","en":"When a river is high, it contains much more water than usual.","ex":{"en":"The waters of the Yangtze River are dangerously high for the time of year.","cn":"长江的水位每年这个时候都处于危险的高位。"}},{"pos":"ADJ-GRADED 能被表示程度的副词或介词词组修饰的形容词","cn":"兴奋的;兴高采烈的","en":"If your spirits are high, you feel happy and excited.","ex":{"en":"Her spirits were high with the hope of seeing Nick in minutes rather than hours.","cn":"她很兴奋，因为再过几分钟而不是几小时后就有希望见到尼克了。"}},{"pos":"ADJ 形容词","cn":"喝醉了的;（吸毒后）极度兴奋的","en":"If someone is high on drink or drugs, they are affected by the alcoholic drink or drugs they have taken.","ex":{"en":"He was too high on drugs and alcohol to remember them.","cn":"他吸毒酗酒后处于极度兴奋状态，已经记不得他们了。"}},{"pos":"N-COUNT 可数名词","cn":"兴奋;高兴","en":"A high is a feeling or mood of great excitement or happiness."},{"pos":"PHRASE 短语","cn":"上级;上面","en":"If you say that something came from on high, you mean that it came from a person or place of great authority.","ex":{"en":"Orders had come from on high that extra care was to be taken during this week.","cn":"上面下了命令，本周要格外小心。"}},{"pos":"PHRASE 短语","cn":"陷入困境","en":"If you say that you were left high and dry, you are emphasizing that you were left in a difficult situation and were unable to do anything about it.","ex":{"en":"Schools with better reputations will be flooded with applications while poorer schools will be left high and dry.","cn":"较有名气的学校将会收到如潮水涌至般的申请，而差一些的学校则会陷入招生困境。"}},{"pos":"PHRASE 短语","cn":"起起落落;快乐和痛苦;成功和失败","en":"If you refer to the highs and lows of someone's life or career, you are referring to both the successful or happy times, and the unsuccessful or bad times."},{"pos":"PHRASE 短语","cn":"到处;各处","en":"If you say that you looked high and low for something, you are emphasizing that you looked for it in every place that you could think of."},{"pos":"","cn":"","en":"in high dudgeon→see: ; come hell or high water→see: ; to be high time→see: ;"}]},"examples":[{"en":"A high over southern Europe is bringing fine, sunny weather to all parts.","cn":"欧洲南部上空的高气压正给各地带来阳光灿烂的好天气。"},{"en":"Highs today will be in the region of 25°C.","cn":"今天的最高气温将为 25 摄氏度左右。"}]},"hill":{"media":{"uk":"media/uk/hill__gb_1.mp3","us":"media/us/hill__us_1.mp3"},"oxford":{"phon":"hɪl","pos":"noun","senses":[{"en":"an area of land that is higher than the land around it, but not as high as a mountain","cn":"山丘；小山","g":"[countable]","ex":{"en":"a region of gently rolling hills","cn":"缓缓起伏的丘陵地区"}},{"en":"a slope on a road","cn":"（道路的）斜坡","g":"[countable]","ex":{"en":"The motorcade made its way up the hill.","cn":"车队一路上山。"}},{"en":"Capitol Hill (= used to refer to the US Capitol and the activities that take place there)","cn":"国会山（指美国国会）","g":"[singular]","lab":"North American English, informal，，"}]},"collins":{"senses":[{"pos":"N-COUNT; N-IN-NAMES 名称名词；名称名词","cn":"小山;山冈;山丘","en":"A hill is an area of land that is higher than the land that surrounds it.","ex":{"en":"We trudged up the hill to the stadium.","cn":"我们费力地爬到山上的体育场。"}},{"pos":"PHRASE 短语","cn":"人老珠黄;在走下坡路;在衰退中;过气","en":"If you say that someone is over the hill, you are saying rudely that they are old and no longer fit, attractive, or capable of doing useful work.","ex":{"en":"He doesn't take kindly to suggestions that he is over the hill.","cn":"他不爱听别人说他风光不再。"}}]},"examples":[{"en":"The house is built on the side of a hill overlooking the river.","cn":"房子建在可俯视河流的小山坡上。"},{"en":"Always take care when driving down steep hills.","cn":"下陡坡时一定要小心驾驶。"}]},"hindered":{"lemma":"hinder"},"hinges":{"lemma":"hinge"},"highlighting":{"lemma":"highlight","media":{"uk":"media/uk/highlight__gb_1.mp3","us":"media/us/highlight__us_1.mp3"}},"him":{"media":{"uk":"media/uk/him__gb_1.mp3","us":"media/us/him__us_1.mp3"},"oxford":{"phon":"hɪm","pos":"pronoun","senses":[{"en":"used as the object of a verb, after the verb be or after a preposition to refer to a male person or animal that has already been mentioned or is easily identified","cn":"他，它（用作动词或介词的宾语，或作表语）","lab":"British English","ex":{"en":"When did you see him?","cn":"你什么时候见到他的？"}},{"en":"used when referring to God","cn":"（指上帝）"}]},"collins":{"senses":[{"pos":"PRON-SING 单数型代词","cn":"他;它（指雄性动物）","en":"You use him to refer to a man, boy, or male animal.","ex":{"en":"John's aunt died suddenly and left him a surprisingly large sum","cn":"约翰的婶婶突然去世了，留给他一笔巨额财产。"}},{"pos":"PRON-SING 单数型代词","cn":"（书面英语中泛指人）他，她（有些人不喜欢这种用法，更倾向于使用 him or her 或 them）","en":"In written English, him is sometimes used to refer to a person without saying whether that person is a man or a woman. Some people dislike this use and prefer to use 'him or her' or 'them'.","ex":{"en":"If the child sees the word 'hear', we should show him that this is the base word in 'hearing' and 'hears'.","cn":"如果孩子看到hear这个词，我们就应该告诉他这是hearing和hears的词干。"}},{"pos":"PRON-SING 单数型代词","cn":"（一些宗教中指）上帝","en":"In some religions, Him is used to refer to God.","ex":{"en":"God will help you if you turn to Him in humility and trust.","cn":"如果你怀着一颗谦恭而信任的心向上帝求助，上帝会帮助你。"}}]},"examples":[{"en":"When did you see him?","cn":"你什么时候见到他的？"},{"en":"He took the children with him.","cn":"他带着孩子。"}]},"hinge":{"oxford":{"phon":"hɪndʒ","pos":"noun","senses":[{"en":"a piece of metal, plastic, etc. on which a door, lid or gate moves freely as it opens or closes","cn":"铰链；合叶","ex":{"en":"The door had been pulled off its hinges.","cn":"门从铰链上扯下来了。"}},{"en":"to attach something with a hinge","cn":"给（某物）装铰链","ex":{"en":"The ironing board was set into the wall and hinged at the bottom.","cn":"烫衣板固定在墙上, 底部装有铰链"},"pos":"verb"}]},"collins":{"senses":[{"pos":"N-COUNT 可数名词","cn":"（门等的）铰链，合页","en":"A hinge is a piece of metal, wood, or plastic that is used to join a door to its frame or to join two things together so that one of them can swing freely.","ex":{"en":"The top swung open on well-oiled hinges.","cn":"用润滑良好的铰链固定的盖子一旋转就打开了。"}},{"pos":"","cn":"","en":"相关词组：hinge on"}]},"media":{"img":["media/ldoce/img/hinge.jpg","media/pic/hinge.jpg"],"uk":"media/uk/hinge__gb_1.mp3","us":"media/us/hinge__us_1.mp3"},"examples":[{"en":"His success hinges on how well he does at the interview.","cn":"他能否成功要看他在面试中的表现。"},{"en":"Everything hinges on the outcome of these talks.","cn":"一切都取决于这几次会谈的结果。"}]},"historian":{"media":{"uk":"media/uk/historian__gb_1.mp3","us":"media/us/historian__us_1.mp3"},"oxford":{"phon":"hɪˈstɔːriən","pos":"noun","senses":[{"en":"a person who studies or writes about history; an expert in history","cn":"史学工作者；历史学家","ex":{"en":"No serious historian today accepts this theory.","cn":"当今任何一位严肃的史学家都不会接受这种理论。"}}]},"collins":{"senses":[{"pos":"N-COUNT 可数名词","cn":"历史学家","en":"A historian is a person who specializes in the study of history, and who writes books and articles about it."}]}},"high-tech":{"oxford":{"phon":"ˌhaɪ ˈtek","pos":"adjective","senses":[{"en":"using the most modern methods and machines, especially electronic ones","cn":"高技术的，高科技的（尤指电子方面）","ex":{"en":"high-tech industries","cn":"高科技产业"}},{"en":"very modern in appearance; using modern materials","cn":"样式新颖的；用高新技术材料的","ex":{"en":"a high-tech table made of glass and steel","cn":"用玻璃和钢制成的现代化桌子"}}]},"media":{"uk":"media/uk/high_tech_1_gb_1.mp3","us":"media/us/high_tech_1_us_1.mp3"},"examples":[{"en":"a high-tech table made of glass and steel","cn":"用玻璃和钢制成的现代化桌子"},{"en":"high-tech industries","cn":"高科技产业"}]},"hillocks":{"oxford":{"phon":"ˈhɪlək","pos":"noun","senses":[{"en":"a small hill","cn":"小丘"}]}},"highways":{"lemma":"highway"},"highest":{"lemma":"high"},"historians":{"lemma":"historian"},"hired":{"lemma":"hire"},"hierarchies":{"lemma":"hierarchy"},"hills":{"lemma":"hill"},"hindsight":{"collins":{"senses":[{"pos":"N-UNCOUNT 不可数名词","cn":"后见之明;事后聪明","en":"Hindsight is the ability to understand and realize something about an event after it has happened, although you did not understand or realize it at the time.","ex":{"en":"With hindsight, we'd all do things differently","cn":"有了事后的认识，我们都会以不同的方式行事。"}}]},"ldoce":{"phon":"hwd","pos":"noun","senses":[{"en":"the ability to understand a situation only after it has happened","cn":"事后聪明﹐事后领悟"},{"en":"→ foresight with/in hindsight With hindsight, I should have seen the warning signs.","cn":"事后想来﹐我是应该看见那些警示牌的。 the benefit/wisdom of hindsight With the benefit of hindsight, it’s easy to criticize. 事后指责自然容易。"}]},"vocab":{"pos":"n","senses":[{"en":"People who are able to look back on the past and understand what happened have hindsight . If you go skating on a frozen lake and it cracks, in hindsight you'd know you should've paid attention to the giant \"danger\" sign."}]},"collocations":{"phrases":["PREP. in ~ Their first scheme was deemed, in hindsight, a mistake. | with ~ This all seems obvious with hindsight.","PHRASES (with) the advantage/benefit/wisdom of hindsight It is easy to criticize others when you have the benefit of hindsight."]},"media":{"uk":"media/ldoce/hwd/bre/f/hindsight0205.mp3","us":"media/ldoce/hwd/ame/a/hindsight.mp3"},"examples":[{"en":"With hindsight it is easy to say they should not have released him.","cn":"事后才说他们本不应该释放他，这倒容易。"},{"en":"What looks obvious in hindsight was not at all obvious at the time.","cn":"事后一目了然的事在当时根本看不清。"}],"oxford":{"phon":"ˈhaɪndsaɪt","pos":"noun","senses":[{"en":"the understanding that you have of a situation only after it has happened and that means you would have done things in a different way","cn":"事后聪明；事后的领悟","ex":{"en":"With hindsight it is easy to say they should not have released him.","cn":"事后才说他们本不应该释放他，这倒容易。"}}]}},"hiccup":{"collins":{"senses":[{"pos":"","cn":"","en":"also hiccough."},{"pos":"N-COUNT 可数名词","cn":"小问题;（尤指）暂时的耽搁","en":"You can refer to a small problem or difficulty as a hiccup, especially if it does not last very long or is easily put right.","ex":{"en":"A recent sales hiccup is nothing to panic about","cn":"用不着为最近销售上出现的一点小问题感到惊慌。"}},{"pos":"N-UNCOUNT 不可数名词","cn":"呃逆;打嗝","en":"When you have hiccups, you make repeated sharp sounds in your throat, often because you have been eating or drinking too quickly.","ex":{"en":"A young baby may frequently get a bout of hiccups during or soon after a feed.","cn":"小婴儿进食过程中或刚刚进食后经常会打嗝。"}},{"pos":"N-COUNT 可数名词","cn":"打嗝声","en":"A hiccup is a sound of the kind that you make when you have hiccups."},{"pos":"VERB 动词","cn":"呃逆;打嗝","en":"When you hiccup, you make repeated sharp sounds in your throat.","ex":{"en":"She was still hiccuping from the egg she had swallowed whole.","cn":"刚才一口吞下整个鸡蛋，她现在还在打嗝。"}}]},"ldoce":{"phon":"hwd","pos":"noun","senses":[{"en":"a bad situation that must be dealt with, because it is causing harm or inconvenience, or it is stopping you from doing what you want to do","cn":""},{"en":"a problem that makes it more difficult to do something that you are trying to do","cn":""},{"en":"a problem or several problems that make something difficult, spoil your plans etc","cn":""}]},"collocations":{"phrases":["ADJ. small | loud","VERB + HICCUP give, let out She gave a loud hiccup. 2 (the) hiccups: series of hiccups","QUANT. attack He suddenly had an attack of the hiccups.","VERB + HICCUP get, suffer from I ate too quickly and got hiccups. 3 small problem","ADJ. little, slight | occasional | temporary","PREP. ~ in This one defeat was the only hiccup in the team's steady progress up the League."]},"media":{"uk":"media/ldoce/hwd/bre/e/brelasdehiccup.mp3","us":"media/ldoce/hwd/ame/e/hiccup1.mp3"},"examples":[{"en":"I ate too quickly and got hiccups.","cn":"我吃得太快，结果不断地打嗝。"},{"en":"There was a slight hiccup in the timetable.","cn":"时间安排上出了点小问题。"}],"oxford":{"phon":"ˈhɪkʌp","pos":"noun","senses":[{"en":"a sharp, usually repeated, sound made in the throat, that is caused by a sudden movement of the diaphragm and that you cannot control","cn":"嗝；呃逆","g":"[countable]","ex":{"en":"She gave a loud hiccup.","cn":"她打了一个响嗝。"}},{"en":"a series of hiccups","cn":"一连串的打嗝","g":"[plural]","ex":{"en":"I ate too quickly and got hiccups.","cn":"我吃得太快，结果不断地打嗝。"}},{"en":"a small problem or temporary delay","cn":"小问题；暂时性耽搁","g":"[countable]","lab":"informal","ex":{"en":"There was a slight hiccup in the timetable.","cn":"时间安排上出了点小问题。"}},{"en":"to have (the) hiccups or a single hiccup","cn":"打嗝；打呃","pos":"verb"}]}},"hike":{"collins":{"senses":[{"pos":"N-COUNT 可数名词","cn":"远足;（尤指）徒步旅行","en":"A hike is a long walk in the country, especially one that you go on for pleasure."},{"pos":"VERB 动词","cn":"远足;徒步旅行","en":"If you hike, you go for a long walk in the country.","ex":{"en":"You could hike through the Fish River Canyon","cn":"你可以徒步穿越鱼河峡谷。"}},{"pos":"N-COUNT 可数名词","cn":"（价格、比率、税率或数量的）突然上涨,大幅上升","en":"A hike is a sudden or large increase in prices, rates, taxes, or quantities.","ex":{"en":"...a sudden 1.75 per cent hike in Italian interest rates","cn":"意大利利率1.75%的突然上浮"}},{"pos":"VERB 动词","cn":"使（价格、比率、税率或数量）突然上升，大幅提高","en":"To hike prices, rates, taxes, or quantities means to increase them suddenly or by a large amount.","ex":{"en":"It has now been forced to hike its rates by 5.25 per cent","cn":"它目前已经被迫将利率提高了5.25%。"}},{"pos":"","cn":"","en":"相关词组：hike up"}]},"ldoce":{"phon":"hwd","pos":"noun","senses":[{"en":"an occasion when the amount or number of something becomes bigger","cn":""},{"en":"an increase in the number, size, or importance of something. Growth is also used when saying that a company or a country’s economy becomes more successful","cn":""},{"en":"an increase in the amount of something, or in the standard or level of something","cn":""}]},"vocab":{"pos":"1 v n 2 v n","senses":[{"en":"To hike is to walk a long way at a leisurely pace. You might love to hike in the woods on weekends."}]},"collocations":{"phrases":["ADJ. long | strenuous | ten-mile, two-day, etc.","VERB + HIKE go on The boys have gone on a long hike with the Boy Scouts.","PREP. on a ~ They met on a hike. | ~ from, ~ to It's a hell of a hike from Sydney to Perth."]},"media":{"uk":"media/ldoce/hwd/bre/a/hike_v0205.mp3","us":"media/ldoce/hwd/ame/3/hike1.mp3"},"examples":[{"en":"They went on a ten-mile hike through the forest.","cn":"他们进行了一次穿越森林的十英里徒步旅行。"},{"en":"strong boots for hiking over rough country","cn":"适合在崎岖不平的山路徒步旅行用的结实靴子"}],"oxford":{"phon":"haɪk","pos":"noun","senses":[{"en":"a long walk in the country","cn":"远足；徒步旅行","ex":{"en":"They went on a ten-mile hike through the forest.","cn":"他们进行了一次穿越森林的十英里徒步旅行。"}},{"en":"a large or sudden increase in prices, costs, etc.","cn":"（价格、花费等的）大幅度提高，猛增","lab":"informal","ex":{"en":"a tax/price hike","cn":"税额／价格的大幅度增长"}},{"en":"to go for a long walk in the country, especially for pleasure","cn":"去…远足；做徒步旅行","g":"[intransitive, transitive]","lab":"North American English","ex":{"en":"You'll need some strong boots for hiking over rough country.","cn":"在崎岖不平的地区徒步旅行，你需要结实的靴子。"},"pos":"verb"},{"en":"to spend time hiking for pleasure","cn":"远足；徒步旅行","g":"[intransitive]","ex":{"en":"If the weather's fine, we'll go hiking this weekend.","cn":"如果天气好，我们这个周末就去远足。"},"pos":"verb"},{"en":"to increase prices, taxes, etc. suddenly by large amounts","cn":"把（价格、税率等）大幅提高","g":"[transitive]","ex":{"en":"The government hiked up the price of milk by over 40%.","cn":"政府把牛奶的价格提高了四成多。"},"pos":"verb"}]}},"hinduism":{"collins":{"senses":[{"pos":"N-UNCOUNT 不可数名词","cn":"印度教","en":"Hinduism is an Indian religion. It has many gods and teaches that people have another life on earth after they die."}]},"ldoce":{"phon":"hwd","pos":"noun","senses":[{"en":"the main religion in India, which includes belief in reincarnation","cn":"印度教"}]},"media":{"uk":"media/ldoce/hwd/bre/2/hinduism0205.mp3","us":"media/ldoce/hwd/ame/d/hinduism.mp3"},"oxford":{"phon":"ˈhɪnduːɪzəm","pos":"noun","senses":[{"en":"the main religion of India and Nepal which includes the worship of one or more gods and belief in reincarnation","cn":"印度教（印度和尼泊尔的主要宗教，敬拜一位或多位神祇，相信轮回转世）"}]}},"hindrance":{"collins":{"senses":[{"pos":"N-COUNT 可数名词","cn":"妨碍者;障碍物","en":"A hindrance is a person or thing that makes it more difficult for you to do something.","ex":{"en":"The higher rates have been a hindrance to economic recovery","cn":"高利率已经成为经济复苏的障碍。"}},{"pos":"N-UNCOUNT 不可数名词","cn":"阻碍;妨碍","en":"Hindrance is the act of hindering someone or something.","ex":{"en":"They boarded their flight to Paris without hindrance.","cn":"他们顺利地登上了飞往巴黎的航班。"}}]},"ldoce":{"phon":"hwd","pos":"noun","senses":[{"en":"something that happens which stops you making progress or which makes things worse than they were before","cn":""},{"en":"a problem or difficulty that must be dealt with before you can do or achieve something else","cn":""},{"en":"a fact or situation that will make it very difficult for something to be achieved","cn":""}]},"vocab":{"pos":"n","senses":[{"en":"A hindrance is something in the way, an obstacle. An untied shoelace is a hindrance to walking, and tripping in the lunchroom might be a hindrance to getting a seat at the cool table."}]},"collocations":{"phrases":["ADJ. great","VERB + HINDRANCE be, prove Having a car in the city might prove a hindrance.","PREP. without ~ (formal) The cook needs room to get at the cooker, sink and cupboards without hindrance. | ~ to The new regulations are actu","PHRASES without let or hindrance (law)"]},"media":{"uk":"media/ldoce/hwd/bre/b/hindrance0205.mp3","us":"media/ldoce/hwd/ame/b/hindrance.mp3"},"examples":[{"en":"To be honest, she was more of a hindrance than a help.","cn":"说实在的，她没帮上忙，反而成了累赘。"},{"en":"The high price is a major hindrance to potential buyers.","cn":"价格高是使潜在买主却步的主要因素。"}],"oxford":{"phon":"ˈhɪndrəns","pos":"noun","senses":[{"en":"a person or thing that makes it more difficult for somebody to do something or for something to happen","cn":"造成妨碍的人（或事物）","g":"[countable, usually singular]","ex":{"en":"To be honest, she was more of a hindrance than a help.","cn":"说实在的，她没帮上忙，反而成了累赘。"}},{"en":"the act of making it more difficult for somebody to do something or for something to happen","cn":"妨碍；阻挠","g":"[uncountable]","lab":"formal","ex":{"en":"They were able to complete their journey without further hindrance.","cn":"剩下的旅程他们没再受到阻碍。"}}]}},"hiss":{"collins":{"senses":[{"pos":"VERB 动词","cn":"发出嘶嘶声","en":"To hiss means to make a sound like a long 's'.","ex":{"en":"The tires of Lenny's bike hissed over the wet pavement as he slowed down","cn":"伦尼放缓车速，听到自行车轮胎在湿漉漉的路面上发出嘶嘶的响声。"}},{"pos":"VERB 动词","cn":"低声呵斥","en":"If you hiss something, you say it forcefully in a whisper.","ex":{"en":"'Now, quiet,' my mother hissed","cn":"“好了，安静点，”母亲压低嗓音厉声道。"}},{"pos":"VERB 动词","cn":"（对不喜欢的表演者或发言人）发嘘声，向…喝倒彩","en":"If people hiss at someone such as a performer or a person making a speech, they express their disapproval or dislike of that person by making long loud 's' sounds.","ex":{"en":"One had to listen hard to catch the words of the President's speech as the delegates booed and hissed","cn":"代表们嘘声四起，很难听清总统的讲话。"}}]},"ldoce":{"phon":"hwd","pos":"verb","senses":[{"en":"a continuous high sound when air or gas comes out of something","cn":""},{"en":"to shout 'boo' to show that you do not like a speaker, performance etc","cn":""},{"en":"to make a noise which sounds like 'ssss' to show that you do not like a speaker, performance etc","cn":""}]},"collocations":{"phrases":["ADJ. sharp | faint, soft, low There was a low hiss on the tape. | audible","VERB + HISS give, let out The snake gave a hiss. | hear","PREP. with a ~ She drew in her breath with a hiss. | ~ of We could hear the faint hiss of escaping gas.","PHRASES boos and hisses, a hiss of air, the hiss of a snake • Note at SOUND"]},"media":{"uk":"media/ldoce/hwd/bre/d/hiss0205.mp3","us":"media/ldoce/hwd/ame/c/hiss.mp3"},"examples":[{"en":"The steam escaped with a loud hissing noise.","cn":"蒸汽冒了出来，发出很响的嘶嘶声。"},{"en":"He was booed and hissed off the stage.","cn":"他在一片倒彩声和嘘声中被轰下台。"}],"oxford":{"phon":"hɪs","pos":"verb","senses":[{"en":"to make a sound like a long ‘s’","cn":"发嘶嘶声","g":"[intransitive]","ex":{"en":"The steam escaped with a loud hissing noise.","cn":"蒸汽冒了出来，发出很响的嘶嘶声。"}},{"en":"to make a sound like a long ‘s’ to show disapproval of somebody/something, especially an actor or a speaker","cn":"发嘘声（表示不满，尤指对演员或演讲人）","g":"[transitive, intransitive]","ex":{"en":"He was booed and hissed off the stage.","cn":"他在一片倒彩声和嘘声中被轰下台。"}},{"en":"to say something in a quiet angry voice","cn":"带怒气地低声说出（某事）","g":"[intransitive, transitive]","ex":{"en":"He hissed at them to be quiet.","cn":"他生气地低声要他们安静点。"}},{"en":"a sound like a long ‘s’; this sound used to show disapproval of somebody","cn":"嘶嘶声；嘘声","ex":{"en":"The hiss of air brakes announced the arrival of the tour bus.","cn":"一听到气动刹车的嘶嘶声就知道旅游巴士到了。"},"pos":"noun"}]}},"hip":{"collins":{"senses":[{"pos":"N-COUNT 可数名词","cn":"髋;臀部","en":"Your hips are the two areas at the sides of your body between the tops of your legs and your waist.","ex":{"en":"Tracey put her hands on her hips and sighed.","cn":"特蕾西双手叉腰叹了口气。"}},{"pos":"N-COUNT 可数名词","cn":"髋;髋部（指骨骼）","en":"You refer to the bones between the tops of your legs and your waist as your hips ."},{"pos":"ADJ-GRADED 能被表示程度的副词或介词词组修饰的形容词","cn":"新潮的;赶时髦的","en":"If you say that someone is hip, you mean that they are very modern and follow all the latest fashions, for example in clothes and ideas.","ex":{"en":"...a hip young character with tight-cropped blond hair and stylish glasses.","cn":"留着一头毛寸金发、戴着时尚眼镜的时髦青年"}},{"pos":"N-COUNT 可数名词","cn":"野蔷薇果","en":"A hip is a rosehip ."},{"pos":"EXCLAM 感叹语","cn":"（表示欣赏或赞许的呼声）好啊！加油！万岁！","en":"If a large group of people want to show their appreciation or approval of someone, one of them says 'Hip hip' and they all shout 'hooray'."},{"pos":"PHRASE 短语","cn":"鲁莽行事;轻举妄动;信口开河","en":"If you say that someone shoots from the hip or fires from the hip, you mean that they react to situations or give their opinion very quickly, without stopping to think.","ex":{"en":"Judges don't have to shoot from the hip. They have the leisure to think, to decide.","cn":"法官们不必贸然行事。他们可以不慌不忙地去思考，去决定。"}}]},"ldoce":{"phon":"hwd","pos":"noun","senses":[{"en":"one of the two parts on each side of your body between the top of your leg and your waist","cn":"臀部﹔髋部"},{"en":"the red fruit of some kinds of rose s","cn":"蔷薇果（实）"},{"en":"clothes, styles, places or activities that are fashionable are popular at the present time, but will probably only be popular for a short time","cn":""}]},"collocations":{"phrases":["ADJ. lean, narrow Her hips were still narrow like a girl's. | sturdy, wide | broken, dislocated, fractured | arthritic | artificial","VERB + HIP have/put your hands on He put his hands on his hips and sighed. | roll, sway, swing, wiggle She wiggled her hips seductively as s","HIP + VERB spread Her hips had spread since having a baby.","HIP + NOUN fracture, injury | deformity | operation, replacement My grandmother's having a hip replacement. | bone, joint, socket | flask He","PREP. across the ~s She was wearing a short blue dress, belted across the hips. | at the ~ He had his leg amputated at the hip. | from the ~","PHRASES hands on hips He leaned casually against the door frame, hands on hips."]},"media":{"uk":"media/ldoce/hwd/bre/2/brelasdehip.mp3","us":"media/ldoce/hwd/ame/1/hip1.mp3"},"examples":[{"en":"‘Three cheers for the bride and groom: Hip, hip … ’ ‘Hooray!’ “","cn":"向新娘和新郎欢呼三声：嘿嘿 … ” “好哪！”"},{"en":"These jeans are too tight around the hips.","cn":"这条牛仔裤的臀部太窄。"}],"oxford":{"phon":"hɪp","pos":"noun","senses":[{"en":"the area at either side of the body between the top of the leg and the middle part of the body; the joint at the top of the leg that connects it with the top part of the body","cn":"臀部；髋","lab":"informal","ex":{"en":"She stood with her hands on her hips.","cn":"她双手叉腰站着。"}},{"en":"having hips of the size or shape mentioned","cn":"臀部…的","ex":{"en":"large-hipped","cn":"臀部大的"}},{"en":"the red fruit that grows on some types of wild rose bush","cn":"野蔷薇果"},{"en":"following or knowing what is fashionable in clothes, music, etc.","cn":"（衣服、音乐等方面）时髦的，赶时髦的","ex":{"en":"He's just trying to be hip!","cn":"他只是想时髦一点！"},"pos":"adjective"}]}},"hitch":{"collins":{"senses":[{"pos":"N-COUNT 可数名词","cn":"（短暂的）小故障，小障碍","en":"A hitch is a slight problem or difficulty which causes a short delay.","ex":{"en":"After some technical hitches the show finally got under way","cn":"一些小技术故障解决后，演出终于开始了。"}},{"pos":"VERB 动词","cn":"搭便车（旅行）；搭顺风车","en":"If you hitch ,hitch a lift, or hitch a ride, you hitchhike.","ex":{"en":"There was no garage in sight, so I hitched a lift into town","cn":"放眼望去看不到修车厂，所以我就搭顺风车进了城。"}},{"pos":"VERB 动词","cn":"把…钩（或拴、系）在…上","en":"If you hitch something to something else, you hook it or fasten it there.","ex":{"en":"Last night we hitched the horse to the cart and moved here.","cn":"昨晚我们套上马车，拉着东西搬到了这里。"}},{"pos":"PHRASE 短语","cn":"结婚","en":"If you get hitched, you get married.","ex":{"en":"The report shows that fewer couples are getting hitched.","cn":"报告显示，结婚的人数呈下降趋势。"}},{"pos":"","cn":"","en":"相关词组：hitch up"}]},"ldoce":{"phon":"hwd","pos":"verb","senses":[{"en":"to get free rides from the drivers of passing cars by standing at the side of the road and putting a hand out with the thumb raised","cn":"搭便车﹐免费搭〔车〕"},{"en":"to move a piece of clothing you are wearing so that it is higher than it was before","cn":"把〔衣物〕向上拉"},{"en":"to get married","cn":"结婚"}]},"vocab":{"pos":"1 v n 2 n 3 v 4 v n ","senses":[{"en":"A hitch is an obstacle or hindrance. You might be late because of a last minute hitch , like waiting for a family of ducks to cross the road. If things go well, they go off without a hitch ."}]},"collocations":{"phrases":["ADJ. slight | last-minute There are always a few last-minute hitches at the dress rehearsal. | legal, technical There was a slight technical","PREP. without a ~ Everything went without a hitch. | ~ in There's been a hitch in the plans."]},"media":{"uk":"media/ldoce/hwd/bre/f/brelasdehitch.mp3","us":"media/ldoce/hwd/ame/7/hitch1.mp3"},"examples":[{"en":"We spent the summer hitching around Europe.","cn":"我们藉搭便车在欧洲各地旅行了一个夏天。"},{"en":"They hitched a ride in a truck.","cn":"他们搭乘了一辆路过的货车。"}],"oxford":{"phon":"hɪtʃ","pos":"verb","senses":[{"en":"to get a free ride in a person’s car; to travel around in this way, by standing at the side of the road and trying to get passing cars to stop","cn":"免费搭车；搭便车","g":"[transitive, intransitive]","lab":"British English also","ex":{"en":"They hitched a ride in a truck.","cn":"他们搭乘了一辆路过的货车。"}},{"en":"to pull up a piece of your clothing","cn":"提起，拉起（衣服）","g":"[transitive]","ex":{"en":"She hitched up her skirt and waded into the river.","cn":"她提起裙子，蹚进河里。"}},{"en":"to lift yourself into a higher position, or the position mentioned","cn":"攀上；跃上","g":"[transitive]","ex":{"en":"She hitched herself up.","cn":"她爬了上去。"}},{"en":"to tie or fasten something to something else with a rope, a hook, etc.","cn":"拴住；套住；钩住","g":"[transitive]","ex":{"en":"She hitched the pony to the gate.","cn":"她把小马拴在大门上。"}},{"en":"a problem or difficulty that causes a short delay","cn":"暂时的困难（或问题）；故障；障碍","ex":{"en":"The ceremony went off without a hitch.","cn":"仪式进行得很顺利。"},"pos":"noun"},{"en":"a type of knot (= a join made by tying together two pieces or ends of rope, etc.)","cn":"（某种）结","ex":{"en":"a clove hitch","cn":"双套结"},"pos":"noun"}]}},"hiv":{"collins":{"senses":[{"pos":"N-UNCOUNT 不可数名词","cn":"人类免疫缺陷病毒;艾滋病病毒","en":"HIV is a virus which reduces people's resistance to illness and can cause AIDS. HIV is an abbreviation for (缩略=) 'hu-man immunodeficiency virus'."},{"pos":"PHRASE 短语","cn":"艾滋病病毒检测呈阳性的/阴性的","en":"If someone is HIV positive, they are infected with the HIV virus, and may develop AIDS. If someone is HIV negative, they are not infected with the virus."}]},"ldoce":{"phon":"hwd","pos":"noun","senses":[{"en":"a type of virus (= a very small living thing that causes disease ) that enters the body through blood or sexual activity, and can develop into AIDS","cn":"人类免疫缺陷病毒﹐艾滋病病毒"}]},"collocations":{"phrases":["VERB + HIV be at risk from | contract, get | have, suffer from people suffering from HIV and Aids | be affected by, be infected by | spread,","HIV + NOUN infection | antibody, virus | carrier, sufferer | status If you are unsure of your HIV status, consider having a test. | test","PHRASES HIV negative/positive •"]},"media":{"uk":"media/ldoce/hwd/bre/3/brelasdehiv.mp3","us":"media/ldoce/hwd/ame/7/hiv.mp3"},"examples":[{"en":"to be HIV-positive/HIV-negative (= to have had a medical test which shows that you are/are not infected with HIV)","cn":"人体免疫缺损病毒检测呈阳性/阴性反应"},{"en":"to be infected with HIV","cn":"染上艾滋病病毒"}],"oxford":{"phon":"ˌeɪtʃ aɪ ˈviː","pos":"noun","senses":[{"en":"the virus that can cause AIDS (the abbreviation for ‘human immunodeficiency virus’)","cn":"人类免疫缺陷病毒，艾滋病病毒（全写为 human immunodeficiency virus）","ex":{"en":"to have HIV","cn":"感染艾滋病毒"}}]}},"himalayas":{"ldoce":{"phon":"hwd","pos":"","senses":[{"en":"a long range of mountains in southern Asia which includes the highest mountain in the world, Mount everest , and other mountains which only very experienced climbers try to climb","cn":""}]},"media":{"uk":"media/ldoce/hwd/bre/7/p028-000006080.mp3","us":"media/ldoce/hwd/ame/7/p028-000006080.mp3"}},"hierarchy":{"collins":{"senses":[{"pos":"N-VAR 可变名词","cn":"等级制度","en":"A hierarchy is a system of organizing people into different ranks or levels of importance, for example in society or in a company.","ex":{"en":"Like most other American companies with a rigid hierarchy, workers and managers had strictly defined duties","cn":"和其他多数拥有严格等级制度的美国公司一样，这里的工人和管理人员都有界定严格的职责。"}},{"pos":"N-COUNT-COLL 可数集合名词","cn":"（组织中的）掌权集团，统治集团","en":"The hierarchy of an organization such as the Church is the group of people who manage and control it."},{"pos":"N-COUNT 可数名词","cn":"（思想、信仰的）等级体系，分级结构","en":"A hierarchy of ideas and beliefs involves organizing them into a system or structure.","ex":{"en":"...the notion of 'cultural imperialism' implies a hierarchy of cultures, some of which are stronger than others.","cn":"“文化扩张主义”意味着一种文化等级体系的存在，其中有些文化要比其他文化更强大。"}}]},"ldoce":{"phon":"hwd","pos":"noun","senses":[{"en":"your job in an organization, company, or profession - use this to talk about how important someone is and how much responsibility they have","cn":""},{"en":"all the jobs in an organization that are similar in importance and that pay similar amounts of money","cn":""},{"en":"someone's position in an organization such as the army or police force","cn":""}]},"vocab":{"pos":"n","senses":[{"en":"Hierarchy describes a system that organizes or ranks things, often according to power or importance. At school the principal is at the top of the staff hierarchy , while the seniors rule the student hierarchy ."}]},"collocations":{"phrases":["ADJ. complex | rigid, strict the rigid class hierarchy of rural society | administrative, bureaucratic, corporate, management, managerial, o","VERB + HIERARCHY create, establish A new management hierarchy was created within the company. | move up, rise in/through He joined the party","PREP. in a/the ~ She is above me in the hierarchy. | within a/the ~ There was a range of opinion within the ecclesiastical hierarchy on the ","PHRASES sb's level/position/status in a hierarchy"]},"media":{"uk":"media/ldoce/hwd/bre/a/hierarchy0205.mp3","us":"media/ldoce/hwd/ame/e/hierarchy.mp3"},"examples":[{"en":"She's quite high up in the management hierarchy.","cn":"她位居管理层要职。"},{"en":"the social/political hierarchy","cn":"社会/政治等级制度"}],"oxford":{"phon":"ˈhaɪərɑːki","pos":"noun","senses":[{"en":"a system, especially in a society or an organization, in which people are organized into different levels of importance from highest to lowest","cn":"等级制度（尤指社会或组织）","g":"[countable, uncountable]","ex":{"en":"the social/political hierarchy","cn":"社会／政治等级制度"}},{"en":"the group of people in control of a large organization or institution","cn":"统治集团","g":"[countable + singular or plural verb]","ex":{"en":"It was on orders from the party hierarchy that she dropped the investigation.","cn":"她是根据党内高层的命令放弃调查的。"}},{"en":"a system that ideas or beliefs can be arranged into according to their importance","cn":"层次体系","g":"[countable]","lab":"formal","ex":{"en":"a hierarchy of needs","cn":"不同层次的需要"}}]}},"hierarchical":{"collins":{"senses":[{"pos":"ADJ-GRADED 能被表示程度的副词或介词词组修饰的形容词","cn":"等级制度的;等级森严的","en":"A hierarchical system or organization is one in which people have different ranks or positions, depending on how important they are.","ex":{"en":"...the traditional hierarchical system of military organization.","cn":"军事组织内传统的等级制度"}}]},"ldoce":{"phon":"hwd","pos":"adjective","senses":[{"en":"if a system, organization etc is hierarchical, people or things are divided into levels of importance","cn":"按等级划分的﹔等级制度的"},{"en":"hierarchical structure/organization/system etc a hierarchical society","cn":"等级社会"}]},"vocab":{"pos":"adj","senses":[{"en":"If something is hierarchical it has clear levels of power and importance, such as a hierarchical corporation that has the boss at the top, or the hierarchical social order of junior high school popularity."}]},"collocations":{"phrases":["VERBS be The company's structure is rigidly hierarchical. | become","ADV. extremely, rigidly, strictly, strongly, very | fairly | essentially"]},"media":{"uk":"media/ldoce/hwd/bre/4/ld41hierarchical.mp3","us":"media/ldoce/hwd/ame/4/ld41hierarchical.mp3"},"examples":[{"en":"a hierarchical society/structure/organization","cn":"分等级的社会/结构/组织"}],"oxford":{"phon":"ˌhaɪəˈrɑːkɪkl","pos":"adjective","senses":[{"en":"arranged in a hierarchy","cn":"按等级划分的；等级制度的","ex":{"en":"a hierarchical society/structure/organization","cn":"分等级的社会／结构／组织"}}]}}});
